-- Editorial enrichment for every published museum-category place.
-- Research verified against the recorded sources on 2026-10-14.
CREATE TABLE IF NOT EXISTS place_editorial_sources (
  place_id TEXT NOT NULL REFERENCES places(id) ON DELETE CASCADE,
  source_url TEXT NOT NULL,
  source_kind TEXT NOT NULL DEFAULT 'official-or-authoritative',
  verified_at TEXT NOT NULL,
  PRIMARY KEY(place_id, source_url)
);
CREATE INDEX IF NOT EXISTS idx_editorial_sources_place ON place_editorial_sources(place_id);

UPDATE places SET description_en='Marble Hill House is a Neo-Palladian villa, now Grade I listed, in Twickenham in the London Borough of Richmond upon Thames. It was built between 1724 and 1729 as the home of Henrietta Howard, Countess of Suffolk, who lived there until her death. The compact design soon became famous and furnished a standard model for the Georgian English villa and for plantation houses in the American colonies.', description_it='Marble Hill House è una villa Neo-Palladian, ora Grade I elencato, a Twickenham nel London Borough di Richmond su Thames. Fu costruita tra il 1724 e il 1729 come casa di Henrietta Howard, contessa di Suffolk, che visse fino alla sua morte. Il design compatto divenne presto famoso e arredato un modello standard per la villa inglese georgiana e per le case di piantagioni nelle colonie americane.',
  editorial_hook_en='Marble Hill House is a Neo-Palladian villa, now Grade I listed, in Twickenham in the London Borough of Richmond upon Thames.', editorial_hook_it='Marble Hill House è una villa Neo-Palladian, ora Grade I elencato, a Twickenham nel London Borough di Richmond su Thames.',
  official_url='', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-026EFE71' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://en.wikipedia.org/wiki/Marble_Hill_House','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-026EFE71'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Somerset House is a large neoclassical building complex situated on the south side of the Strand in central London, overlooking the River Thames, just east of Waterloo Bridge. The Georgian era quadrangle is built on the site of a Tudor palace ("Old Somerset House") originally belonging to Edward Seymour, 1st Duke of Somerset.', description_it='Somerset House è un grande complesso di edifici neoclassici situato sul lato sud del Strand nel centro di Londra, affacciato sul Tamigi, a est del Ponte Waterloo. Il quadrango di epoca georgiano è costruito sul sito di un palazzo di Tudor ("Casa Vecchia Somerset") originariamente appartenente a Edward Seymour, I duca di Somerset.',
  editorial_hook_en='Somerset House is a large neoclassical building complex situated on the south side of the Strand in central London, overlooking the River Thames, just east of Waterloo Bridge.', editorial_hook_it='Somerset House è un grande complesso di edifici neoclassici situato sul lato sud del Strand nel centro di Londra, affacciato sul Tamigi, a est del Ponte Waterloo.',
  official_url='https://www.somersethouse.org.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-3C223037' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://en.wikipedia.org/wiki/Somerset_House','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-3C223037'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Tate Modern is an art gallery in London, housing the United Kingdom''s national collection of international modern and contemporary art (created from or after 1900). It forms part of the Tate group together with Tate Britain, Tate Liverpool and Tate St Ives. It is located in the former Bankside Power Station, in the Bankside area of the London Borough of Southwark.', description_it='Tate Modern è una galleria d''arte a Londra, che ospita la collezione nazionale del Regno Unito di arte moderna e contemporanea internazionale (creata da o dopo il 1900). Fa parte del gruppo Tate insieme a Tate Britain, Tate Liverpool e Tate St Ives. Si trova nella ex Bankside Power Station, nella zona Bankside del London Borough di Southwark.',
  editorial_hook_en='Tate Modern is an art gallery in London, housing the United Kingdom''s national collection of international modern and contemporary art (created from or after 1900).', editorial_hook_it='Tate Modern è una galleria d''arte a Londra, che ospita la collezione nazionale del Regno Unito di arte moderna e contemporanea internazionale (creata da o dopo il 1900).',
  official_url='https://www.tate.org.uk/modern', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-09A19EC7' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://en.wikipedia.org/wiki/Tate_Modern','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-09A19EC7'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Victoria and Albert Museum (abbreviated V&A) in the United Kingdom is the world''s largest museum of applied arts, decorative arts and design, housing a permanent collection of over 2. 8 million objects. The Victoria and Albert Museum collection is housed across six sites in the United Kingdom. This "family of museums" comprises;- V&A South Kensington, the museum''s original London site which covers 12.', description_it='Il Victoria and Albert Museum (abbreviato V&A) nel Regno Unito è il più grande museo mondiale di arti applicate, arti decorative e design, che ospita una collezione permanente di oltre 2. 8 milioni di oggetti. La collezione Victoria and Albert Museum è ospitata in sei siti nel Regno Unito. Questa "famiglia dei musei" comprende;- V&A South Kensington, l''originale sito di Londra del museo che copre 12.',
  editorial_hook_en='The Victoria and Albert Museum (abbreviated V&A) in the United Kingdom is the world''s largest museum of applied arts, decorative arts and design, housing a permanent collection of over 2.', editorial_hook_it='Il Victoria and Albert Museum (abbreviato V&A) nel Regno Unito è il più grande museo mondiale di arti applicate, arti decorative e design, che ospita una collezione permanente di oltre 2.',
  official_url='https://www.vam.ac.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-4CB4F3CA' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
