UPDATE places SET description_en='Tate Britain, known from 1897 to 1932 as the National Gallery of British Art and from 1932 to 2000 as the Tate Gallery, is an art museum on Millbank in the City of Westminster in London, England. It is part of the Tate network of galleries in England, with Tate Modern, Tate Liverpool and Tate St Ives.', description_it='Tate Britain, conosciuta dal 1897 al 1932 come National Gallery of British Art e dal 1932 al 2000 come Tate Gallery, è un museo d''arte a Millbank nella città di Westminster a Londra, Inghilterra. Fa parte della rete Tate di gallerie in Inghilterra, con Tate Modern, Tate Liverpool e Tate St Ives.',
  editorial_hook_en='Tate Britain, known from 1897 to 1932 as the National Gallery of British Art and from 1932 to 2000 as the Tate Gallery, is an art museum on Millbank in the City of Westminster in London, England.', editorial_hook_it='Tate Britain, conosciuta dal 1897 al 1932 come National Gallery of British Art e dal 1932 al 2000 come Tate Gallery, è un museo d''arte a Millbank nella città di Westminster a Londra, Inghilterra.',
  official_url='https://www.tate.org.uk/britain/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-20B94324' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://en.wikipedia.org/wiki/Tate_Britain','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-20B94324'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Museum of Richmond in the London Borough of Richmond upon Thames is located in Richmond''s Old Town Hall, close to Richmond Bridge. It was formally opened by Queen Elizabeth II on 28 October 1988. An independent museum and a registered charity, it is supported by Richmond upon Thames Borough Council.', description_it='Il Museo di Richmond nel Borough di Londra di Richmond sul Tamigi si trova nel centro storico di Richmond, vicino al Ponte Richmond. Fu formalmente aperta dalla Regina Elisabetta II il 28 ottobre 1988. Un museo indipendente e una carità registrata, è supportato da Richmond su Thames Borough Council.',
  editorial_hook_en='The Museum of Richmond in the London Borough of Richmond upon Thames is located in Richmond''s Old Town Hall, close to Richmond Bridge.', editorial_hook_it='Il Museo di Richmond nel Borough di Londra di Richmond sul Tamigi si trova nel centro storico di Richmond, vicino al Ponte Richmond.',
  official_url='https://www.museumofrichmond.com/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-F1374288' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://en.wikipedia.org/wiki/Museum_of_Richmond','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-F1374288'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Foundling Museum in Bloomsbury tells the moving story of Britain’s first children’s charity and the Foundling Hospital. Galleries display Hogarth and Handel connections, social history, portraits and decorative arts alongside personal objects and archives. Evocative rooms, family trails, talks and temporary exhibitions bring lives and reform to life. A welcoming shop and café make it a thoughtful, accessible stop for curious visitors', description_it='Il Foundling Museum di Bloomsbury racconta la commovente storia dei primi bambini della Gran Bretagna e del Foundling Hospital. Gallerie espongono connessioni Hogarth e Handel, storia sociale, ritratti e arti decorative insieme oggetti personali e archivi. Sale evocative, percorsi familiari, colloqui e mostre temporanee portano vita e riforma alla vita. Un accogliente negozio e caffè lo rendono una sosta piacevole e accessibile per i visitatori curiosi',
  editorial_hook_en='Foundling Museum in Bloomsbury tells the moving story of Britain’s first children’s charity and the Foundling Hospital.', editorial_hook_it='Il Foundling Museum di Bloomsbury racconta la commovente storia dei primi bambini della Gran Bretagna e del Foundling Hospital.',
  official_url='https://foundlingmuseum.org.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='M7' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://foundlingmuseum.org.uk/','official-or-authoritative','2026-10-14' FROM places WHERE id='M7'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The British Library is the national library of the United Kingdom. Based in London, it is one of the largest libraries in the world, with an estimated collection of over 200 million items from multiple countries. As a legal deposit library, it receives copies of all books produced in the United Kingdom and Ireland, as well as a significant proportion of overseas titles distributed in the United Kingdom.', description_it='La British Library è la biblioteca nazionale del Regno Unito. Con sede a Londra, è una delle più grandi biblioteche del mondo, con una raccolta stimata di oltre 200 milioni di articoli provenienti da più paesi. Come biblioteca legale, riceve copie di tutti i libri prodotti nel Regno Unito e in Irlanda, nonché una percentuale significativa di titoli all''estero distribuiti nel Regno Unito.',
  editorial_hook_en='The British Library is the national library of the United Kingdom. Based in London, it is one of the largest libraries in the world, with an estimated collection of over 200 million items from multiple countries.', editorial_hook_it='La British Library è la biblioteca nazionale del Regno Unito. Con sede a Londra, è una delle più grandi biblioteche del mondo, con una raccolta stimata di oltre 200 milioni di articoli provenienti da più paesi.',
  official_url='https://bl.uk', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-63D04225' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://en.wikipedia.org/wiki/British_Library','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-63D04225'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Churchill War Rooms is a museum in London and one of the five branches of the Imperial War Museum. The museum comprises the Cabinet War Rooms, a historic underground complex that housed a British government command centre throughout the Second World War, and the Churchill Museum, a biographical museum exploring the life of British statesman Winston Churchill.', description_it='Il Churchill War Rooms è un museo a Londra e uno dei cinque rami del Imperial War Museum. Il museo comprende le Cabinet War Rooms, un complesso sotterraneo storico che ospitava un centro di comando del governo britannico durante la seconda guerra mondiale, e il Churchill Museum, un museo biografico che esplora la vita dello statista britannico Winston Churchill.',
  editorial_hook_en='The Churchill War Rooms is a museum in London and one of the five branches of the Imperial War Museum.', editorial_hook_it='Il Churchill War Rooms è un museo a Londra e uno dei cinque rami del Imperial War Museum.',
  official_url='https://www.iwm.org.uk/visits/churchill-war-rooms', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-1986A3A5' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://en.wikipedia.org/wiki/Churchill_War_Rooms','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-1986A3A5'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Mosaic Rooms is a non-profit gallery in a converted Kensington townhouse devoted to modern and contemporary culture from the Arab world and beyond. Its changing exhibitions, commissions, talks and family programme foreground artists and ideas that remain underrepresented in London’s larger institutions.', description_it='Il Mosaic Rooms è una galleria senza scopo di lucro in una residenza cittadina convertita di Kensington dedicata alla cultura moderna e contemporanea dal mondo arabo e oltre. Le sue mutevoli mostre, commissioni, colloqui e programma di famiglia per artisti e idee che rimangono sottorappresentate nelle più grandi istituzioni londinesi.',
  editorial_hook_en='The Mosaic Rooms is a non-profit gallery in a converted Kensington townhouse devoted to modern and contemporary culture from the Arab world and beyond.', editorial_hook_it='Il Mosaic Rooms è una galleria senza scopo di lucro in una residenza cittadina convertita di Kensington dedicata alla cultura moderna e contemporanea dal mondo arabo e oltre.',
  official_url='https://mosaicrooms.org/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-A6D97EAA' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://mosaicrooms.org/','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-A6D97EAA'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Bruce Castle (formerly the Lordship House) is a Grade I listed 16th-century manor house in Lordship Lane, Tottenham, London. It is named after the House of Bruce who formerly owned the land on which it is built. Believed to stand on the site of an earlier building, about which little is known, the current house is one of the oldest surviving English brick houses.', description_it='Bruce Castle (ex Lordship House) è una casa padronale del XVI secolo a Lordship Lane, Tottenham, Londra. Prende il nome dalla Casa di Bruce che precedentemente possedeva la terra su cui è costruita. Pensato per stare sul sito di un edificio precedente, su cui poco è noto, la casa attuale è una delle più antiche case di mattoni inglesi sopravvissuti.',
  editorial_hook_en='Bruce Castle (formerly the Lordship House) is a Grade I listed 16th-century manor house in Lordship Lane, Tottenham, London.', editorial_hook_it='Bruce Castle (ex Lordship House) è una casa padronale del XVI secolo a Lordship Lane, Tottenham, Londra.',
  official_url='https://www.brucecastle.org/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-C8D68769' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://en.wikipedia.org/wiki/Bruce_Castle','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-C8D68769'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Van Gogh House preserves 87 Hackford Road, where the young Vincent van Gogh lodged in 1873 while working for an art dealer. Restored rooms, archival research, artist commissions and a garden inspired by his letters use this modest Stockwell terrace to explore a formative London chapter in his life.', description_it='Van Gogh House conserva 87 Hackford Road, dove il giovane Vincent van Gogh si trovava nel 1873 mentre lavorava per un commerciante d''arte. Sale restaurate, ricerca archivistica, commissioni d''artista e un giardino ispirato alle sue lettere usano questa modesta terrazza Stockwell per esplorare un capitolo formativo di Londra nella sua vita.',
  editorial_hook_en='Van Gogh House preserves 87 Hackford Road, where the young Vincent van Gogh lodged in 1873 while working for an art dealer.', editorial_hook_it='Van Gogh House conserva 87 Hackford Road, dove il giovane Vincent van Gogh si trovava nel 1873 mentre lavorava per un commerciante d''arte.',
  official_url='https://vangoghhouse.co.uk/', access_notes_en='Admission, timed-entry and opening arrangements can change. Check the official site for current tickets, concessions, sold-out periods and temporary closures before travelling.', access_notes_it='Biglietti, fasce orarie e aperture possono cambiare. Controlla il sito ufficiale per prezzi, riduzioni, esaurimenti e chiusure temporanee prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-036A9AA2' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://vangoghhouse.co.uk/','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-036A9AA2'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Dorich House was completed in 1936 as the studio-home of sculptor Dora Gordine and her husband Richard Hare. The striking red-brick house combines dramatic double-height studios, Art Deco interiors and displays of Gordine’s sculpture with the couple’s collection of Russian art and furniture.', description_it='Dorich House fu completata nel 1936 come studio-casa dello scultore Dora Gordine e suo marito Richard Hare. L’affascinante casa in mattoni rossi combina i drammatici studi a doppia altezza, gli interni Art Deco e le esposizioni della scultura di Gordine con la collezione di arte e mobili russi della coppia.',
  editorial_hook_en='Dorich House was completed in 1936 as the studio-home of sculptor Dora Gordine and her husband Richard Hare.', editorial_hook_it='Dorich House fu completata nel 1936 come studio-casa dello scultore Dora Gordine e suo marito Richard Hare.',
  official_url='https://www.kingston.ac.uk/about/community/dorich-house-museum', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-E693BCDF' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://www.kingston.ac.uk/about/community/dorich-house-museum','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-E693BCDF'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

