UPDATE places SET description_en='The Wallace Collection is a museum in London occupying Hertford House in Manchester Square, the former townhouse of the Seymour family, Marquesses of Hertford. It is named after Sir Richard Wallace, who built the extensive collection, along with the Marquesses of Hertford, in the 18th and 19th centuries.', description_it='La Wallace Collection è un museo a Londra che occupa Hertford House a Manchester Square, l''ex residenza comunale della famiglia Seymour, Marquesses of Hertford. Prende il nome da Sir Richard Wallace, che costruì la vasta collezione, insieme alle Marchese di Hertford, nel XVIII e XIX secolo.',
  editorial_hook_en='The Wallace Collection is a museum in London occupying Hertford House in Manchester Square, the former townhouse of the Seymour family, Marquesses of Hertford.', editorial_hook_it='La Wallace Collection è un museo a Londra che occupa Hertford House a Manchester Square, l''ex residenza comunale della famiglia Seymour, Marquesses of Hertford.',
  official_url='https://www.wallacecollection.org', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-CE730E4E' AND category='MUSEUM';
