UPDATE places SET description_en='Whitehall is a road and area in the City of Westminster, Central London, England. The road forms the first part of the A3212 road from Trafalgar Square to Chelsea. It is the main thoroughfare running south from Trafalgar Square towards Parliament Square. The street is recognised as the centre of the Government of the United Kingdom and is lined with numerous departments and ministries, including the Ministry of Defence, Horse Guards, the Cabinet Office, and much of the Foreign Office.', description_it='Whitehall è una strada e una zona nella città di Westminster, nel centro di Londra, in Inghilterra. La strada forma la prima parte della strada A3212 da Trafalgar Square a Chelsea. È la via principale che corre a sud da Trafalgar Square verso Parliament Square. La strada è riconosciuta come il centro del governo del Regno Unito ed è allineata con numerosi dipartimenti e ministeri, tra cui il Ministero della Difesa, le Guardie di Cavallo, l''Ufficio del Gabinetto e gran parte dell''Ufficio degli Esteri.',
  editorial_hook_en='Whitehall is a road and area in the City of Westminster, Central London, England.', editorial_hook_it='Whitehall è una strada e una zona nella città di Westminster, nel centro di Londra, in Inghilterra.',
  official_url='', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-733D46DF' AND category='MUSEUM';
