UPDATE places SET description_en='The Estorick Collection of Modern Italian Art is a museum in Canonbury Square in the district of Islington, London in the United Kingdom. It is the country''s only gallery devoted to modern Italian art and is a registered charity. The Estorick Collection was founded by the American sociologist and writer Eric Estorick (1913–1993), who began to collect art when he moved to England after the Second World War.', description_it='L''Estorick Collection of Modern Italian Art è un museo a Canonbury Square nel quartiere di Islington, Londra nel Regno Unito. È l''unica galleria del paese dedicata all''arte moderna italiana ed è una carità registrata. La Collezione Estorick fu fondata dal sociologo e scrittore statunitense Eric Estorick (1913-1993), che iniziò a raccogliere l''arte quando si trasferì in Inghilterra dopo la seconda guerra mondiale.',
  editorial_hook_en='The Estorick Collection of Modern Italian Art is a museum in Canonbury Square in the district of Islington, London in the United Kingdom.', editorial_hook_it='L''Estorick Collection of Modern Italian Art è un museo a Canonbury Square nel quartiere di Islington, Londra nel Regno Unito.',
  official_url='https://www.estorickcollection.com', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-0A10A6A4' AND category='MUSEUM';
