UPDATE places SET description_en='The Newport Street Gallery is an art gallery in London, England, created by contemporary artist Damien Hirst for the display of works from his personal art collection, and as a venue to put on exhibitions of interest to him. The Grade II listed building, formerly Hirst''s studio, was awarded the RIBA Stirling Prize following its conversion in 2016 by Caruso St John Architects.', description_it='La Newport Street Gallery è una galleria d''arte a Londra, Inghilterra, creata dall''artista contemporaneo Damien Hirst per la visualizzazione di opere della sua collezione d''arte personale, e come luogo per mettere su mostre di interesse per lui. L''edificio classificato Grade II, ex studio di Hirst, è stato assegnato al RIBA Stirling Prize dopo la sua conversione nel 2016 da Caruso St John Architects.',
  editorial_hook_en='The Newport Street Gallery is an art gallery in London, England, created by contemporary artist Damien Hirst for the display of works from his personal art collection, and as a venue to put on exhibitions of interest to him.', editorial_hook_it='La Newport Street Gallery è una galleria d''arte a Londra, Inghilterra, creata dall''artista contemporaneo Damien Hirst per la visualizzazione di opere della sua collezione d''arte personale, e come luogo per mettere su mostre di interesse per lui.',
  official_url='https://www.newportstreetgallery.com/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-EE0203E2' AND category='MUSEUM';
