UPDATE places SET description_en='The Guildhall Art Gallery houses the art collection of the City of London, England. The museum is located in the Moorgate area of the City of London. It is a stone building in a semi-Gothic style intended to be sympathetic to the historic Guildhall, which is adjacent and to which it is connected internally.', description_it='La Guildhall Art Gallery ospita la collezione d''arte della città di Londra, Inghilterra. Il museo si trova nella zona Moorgate della città di Londra. Si tratta di un edificio in pietra in uno stile semi-gotico destinato ad essere simpatico allo storico Guildhall, che è adiacente e a cui è collegato internamente.',
  editorial_hook_en='The Guildhall Art Gallery houses the art collection of the City of London, England.', editorial_hook_it='La Guildhall Art Gallery ospita la collezione d''arte della città di Londra, Inghilterra.',
  official_url='https://www.cityoflondon.gov.uk/things-to-do/attractions-museums-entertainment/guildhall-art-gallery', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-B47FA9BD' AND category='MUSEUM';
