UPDATE places SET description_en='Lesnes Abbey is a former abbey, now ruined, in Abbey Wood, in the London Borough of Bexley, south-east London, England. It is a scheduled monument, and the abbey''s ruins are listed at Grade II by Historic England. The adjacent Lesnes Abbey Woods are a Local Nature Reserve. Part of the wood is the Abbey Wood SSSI, a geological Site of Special Scientific Interest which is an important site for fossils of the early Tertiary period.', description_it='Lesnes Abbey è un''antica abbazia, ora rovinata, a Abbey Wood, nel London Borough di Bexley, a sud-est di Londra, Inghilterra. È un monumento in programma, e le rovine dell''abbazia sono elencate a Grade II dall''Inghilterra storica. L''adiacente Abbazia di Lesnes Woods è una riserva naturale locale. Parte del bosco è l''Abbazia Wood SSSI, un sito geologico di interesse scientifico speciale che è un importante sito per i fossili del primo periodo terziario.',
  editorial_hook_en='Lesnes Abbey is a former abbey, now ruined, in Abbey Wood, in the London Borough of Bexley, south-east London, England.', editorial_hook_it='Lesnes Abbey è un''antica abbazia, ora rovinata, a Abbey Wood, nel London Borough di Bexley, a sud-est di Londra, Inghilterra.',
  official_url='', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-AC890240' AND category='MUSEUM';
