UPDATE places SET description_en='Queen''s House is a former royal residence in the London borough of Greenwich, which presently serves as a public art gallery. It was built between 1616 and 1635 on the grounds of the now demolished Greenwich Palace, a few miles downriver from the City of London. In its current setting, it forms a central focus of the Old Royal Naval College with a grand vista leading to the River Thames, a World Heritage Site called Maritime Greenwich.', description_it='Queen''s House è un''ex residenza reale nel quartiere di Londra di Greenwich, che attualmente funge da galleria d''arte pubblica. Fu costruito tra il 1616 e il 1635 sul terreno dell''ormai demolita Greenwich Palace, a pochi chilometri di distanza dalla città di Londra. Nella sua impostazione attuale, forma un centro centrale del vecchio Royal Naval College con un grande vista che conduce al Tamigi, un patrimonio mondiale chiamato Maritime Greenwich.',
  editorial_hook_en='Queen''s House is a former royal residence in the London borough of Greenwich, which presently serves as a public art gallery.', editorial_hook_it='Queen''s House è un''ex residenza reale nel quartiere di Londra di Greenwich, che attualmente funge da galleria d''arte pubblica.',
  official_url='https://www.nmm.ac.uk/server/show/nav.3556', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-7FB01F55' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://en.wikipedia.org/wiki/Queen''s_House','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-7FB01F55'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The National Gallery houses the national collection of Western European painting from the thirteenth to the early twentieth century. Works by Van Eyck, Leonardo, Titian, Velázquez, Rembrandt, Turner, Monet and Van Gogh make it possible to trace major shifts in technique and patronage room by room.', description_it='La Galleria Nazionale ospita la collezione nazionale di pittura europea occidentale dal XIII all''inizio del XX secolo. I lavori di Van Eyck, Leonardo, Tiziano, Velázquez, Rembrandt, Turner, Monet e Van Gogh permettono di tracciare i principali turni in tecnica e stanza di patronato per stanza.',
  editorial_hook_en='The National Gallery houses the national collection of Western European painting from the thirteenth to the early twentieth century.', editorial_hook_it='La Galleria Nazionale ospita la collezione nazionale di pittura europea occidentale dal XIII all''inizio del XX secolo.',
  official_url='https://www.nationalgallery.org.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-9E875B3F' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://www.nationalgallery.org.uk/','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-9E875B3F'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Vestry House Museum occupies Walthamstow’s former parish workhouse, built in 1730, and explores local life across several centuries. Domestic objects, photographs, toys, costume and the borough archives sit beside displays on transport and industry, including the story of the locally built Bremer car.', description_it='Il Vestry House Museum occupa l''ex casa di lavoro parrocchiale di Walthamstow, costruita nel 1730, ed esplora la vita locale attraverso diversi secoli. Oggetti domestici, fotografie, giocattoli, costume e gli archivi del quartiere siedono accanto a esposizioni sul trasporto e l''industria, tra cui la storia dell''auto Bremer costruita a livello locale.',
  editorial_hook_en='Vestry House Museum occupies Walthamstow’s former parish workhouse, built in 1730, and explores local life across several centuries.', editorial_hook_it='Il Vestry House Museum occupa l''ex casa di lavoro parrocchiale di Walthamstow, costruita nel 1730, ed esplora la vita locale attraverso diversi secoli.',
  official_url='https://www.walthamforest.gov.uk/libraries-arts-parks-and-leisure/local-history-and-heritage/vestry-house-museum', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-1DE20818' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
