ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Benjamin Franklin House is a museum in a terraced Georgian house at 36 Craven Street, London, close to Trafalgar Square in the West End of London. It is the last-standing former residence of Benjamin Franklin, one of the Founding Fathers of the United States. The house dates from c. 1730, and Franklin lived and worked there from 1757 to 1774, when it was owned by Margaret Stevenson.', description_it='Benjamin Franklin House è un museo in una casa georgiana terrazzata a 36 Craven Street, Londra, vicino a Trafalgar Square nel West End di Londra. È l''ultima residenza di Benjamin Franklin, uno dei padri fondatori degli Stati Uniti. La casa risale a c. 1730, e Franklin visse e vi lavorò dal 1757 al 1774, quando era di proprietà di Margaret Stevenson.',
  editorial_hook_en='Benjamin Franklin House is a museum in a terraced Georgian house at 36 Craven Street, London, close to Trafalgar Square in the West End of London.', editorial_hook_it='Benjamin Franklin House è un museo in una casa georgiana terrazzata a 36 Craven Street, Londra, vicino a Trafalgar Square nel West End di Londra.',
  official_url='https://benjaminfranklinhouse.org', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-9AE40417' AND category='MUSEUM';
