UPDATE places SET description_en='Sambourne House, previously known as 18 Stafford Terrace and Linley Sambourne House, was the home of the Punch illustrator Edward Linley Sambourne (1844–1910) in Kensington, London. The house, now Grade II* listed, is currently open to the public as a museum. In 1875 when the Sambournes moved in, 18 Stafford Terrace was an almost new townhouse.', description_it='Sambourne House, precedentemente conosciuta come 18 Stafford Terrace e Linley Sambourne House, era la sede dell''illustratore di Punch Edward Linley Sambourne (1844-1910) a Kensington, Londra. La casa, ora classificata Grade II*, è attualmente aperta al pubblico come museo. Nel 1875 quando i Sambournes si trasferirono, 18 Stafford Terrace era una casa di città quasi nuova.',
  editorial_hook_en='Sambourne House, previously known as 18 Stafford Terrace and Linley Sambourne House, was the home of the Punch illustrator Edward Linley Sambourne (1844–1910) in Kensington, London.', editorial_hook_it='Sambourne House, precedentemente conosciuta come 18 Stafford Terrace e Linley Sambourne House, era la sede dell''illustratore di Punch Edward Linley Sambourne (1844-1910) a Kensington, Londra.',
  official_url='https://www.rbkc.gov.uk/museums/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-181925DD' AND category='MUSEUM';
