UPDATE places SET description_en='Dennis Severs'' House is a historical tourist attraction at 18 Folgate Street in Spitalfields, within the East End of Central London, England. Created by Dennis Severs, who owned and lived in the house from 1979 to 1999, it is intended as a "historical imagination" of what life would have been like inside for a family of Huguenot silk weavers.', description_it='Dennis Severs'' House è una storica attrazione turistica a 18 Folgate Street a Spitalfields, nell''East End di Central London, Inghilterra. Creato da Dennis Severs, che possedeva e viveva in casa dal 1979 al 1999, è inteso come una "immaginazione storica" di quale sarebbe stata la vita dentro per una famiglia di tessitori di seta Huguenot.',
  editorial_hook_en='Dennis Severs'' House is a historical tourist attraction at 18 Folgate Street in Spitalfields, within the East End of Central London, England.', editorial_hook_it='Dennis Severs'' House è una storica attrazione turistica a 18 Folgate Street a Spitalfields, nell''East End di Central London, Inghilterra.',
  official_url='https://www.dennissevershouse.co.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-B07BA818' AND category='MUSEUM';
