UPDATE places SET description_en='Hogarth''s House is the former country home of the 18th-century English artist William Hogarth in Chiswick, adjacent to the A4. The House now belongs to the London Borough of Hounslow and is open to visitors as a historic house museum free of charge. Chiswick is now one of London''s western suburbs, but in the 18th century it was a large village or small town quite separate from the metropolis, but within easy reach of it.', description_it='Hogarth''s House è l''ex patria dell''artista inglese del XVIII secolo William Hogarth a Chiswick, adiacente all''A4. La Casa appartiene ora al London Borough di Hounslow ed è aperta ai visitatori come museo di casa storica gratuitamente. Chiswick è ora una delle periferie occidentali di Londra, ma nel XVIII secolo era un grande villaggio o piccola città abbastanza separata dalla metropoli, ma a breve distanza.',
  editorial_hook_en='Hogarth''s House is the former country home of the 18th-century English artist William Hogarth in Chiswick, adjacent to the A4.', editorial_hook_it='Hogarth''s House è l''ex patria dell''artista inglese del XVIII secolo William Hogarth a Chiswick, adiacente all''A4.',
  official_url='https://hogarthshouse.org', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-668497A1' AND category='MUSEUM';
