UPDATE places SET description_en='The Saatchi Gallery is a London gallery for contemporary art and an independent charity opened by Charles Saatchi in 1985. Exhibitions which drew upon the collection of Charles Saatchi, starting with US artists and minimalism, moving to the Damien Hirst-led Young British Artists, followed by shows purely of painting, led to Saatchi Gallery becoming a recognised authority in contemporary art globally.', description_it='La Saatchi Gallery è una galleria di Londra per l''arte contemporanea e una carità indipendente aperta da Charles Saatchi nel 1985. Le mostre che hanno tratto la collezione di Charles Saatchi, a partire da artisti e minimalismo americani, passando per i giovani artisti britannici guidati da Damien Hirst, seguiti da spettacoli puramente pittorici, hanno portato alla Saatchi Gallery a diventare un''autorità riconosciuta nell''arte contemporanea a livello globale.',
  editorial_hook_en='The Saatchi Gallery is a London gallery for contemporary art and an independent charity opened by Charles Saatchi in 1985.', editorial_hook_it='La Saatchi Gallery è una galleria di Londra per l''arte contemporanea e una carità indipendente aperta da Charles Saatchi nel 1985.',
  official_url='https://www.saatchi-gallery.co.uk', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-EBA22EA7' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
