UPDATE places SET description_en='Keats House is a writer''s house museum in what was once the home of the Romantic poet John Keats. It is in Keats Grove, Hampstead, in inner north London. Maps before about 1915 show the road with one of its earlier names, John Street; the road has also been known as Albion Grove. The building was originally a pair of semi-detached houses known as "Wentworth Place".', description_it='Keats House è un museo di casa dello scrittore in quella che una volta era la casa del poeta romantico John Keats. È a Keats Grove, Hampstead, nel nord di Londra. Le mappe prima del 1915 mostrano la strada con uno dei suoi nomi precedenti, John Street; la strada è stata anche conosciuta come Albion Grove. L''edificio era originariamente un paio di case semi-indipendenti conosciute come "Wentworth Place".',
  editorial_hook_en='Keats House is a writer''s house museum in what was once the home of the Romantic poet John Keats.', editorial_hook_it='Keats House è un museo di casa dello scrittore in quella che una volta era la casa del poeta romantico John Keats.',
  official_url='https://www.cityoflondon.gov.uk/things-to-do/attractions-museums-entertainment/keats-house', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-BBA939FD' AND category='MUSEUM';
