UPDATE places SET description_en='Valence House is Dagenham’s surviving medieval manor house, surrounded by a moat and later-period gardens. Its museum traces local archaeology, farming, domestic life and the growth of the Becontree Estate, with the borough archive and the Fanshawe family’s notable portraits adding unusual depth.', description_it='Valence House è la casa padronale medievale sopravvissuta di Dagenham, circondata da un fossato e giardini più tardi periodo. Il suo museo ripercorre l''archeologia locale, l''agricoltura, la vita domestica e la crescita della tenuta Becontree, con l''archivio del quartiere e i ritratti notevoli della famiglia Fanshawe aggiungendo una profondità insolita.',
  editorial_hook_en='Valence House is Dagenham’s surviving medieval manor house, surrounded by a moat and later-period gardens.', editorial_hook_it='Valence House è la casa padronale medievale sopravvissuta di Dagenham, circondata da un fossato e giardini più tardi periodo.',
  official_url='https://www.lbbd.gov.uk/valence-house', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-A541888F' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
