UPDATE places SET description_en='Dulwich Picture Gallery is an art gallery in Dulwich, south London, and the oldest public art gallery in England. Opened in 1817 to a design by Regency architect Sir John Soane, it became a landmark in museum architecture through its innovative use of natural light. Originally part of the College of God''s Gift, the charitable foundation established by Edward Alleyn in the early 17th century, the gallery became an independent charitable trust in 1994.', description_it='Dulwich Picture Gallery è una galleria d''arte a Dulwich, nel sud di Londra, e la più antica galleria d''arte pubblica in Inghilterra. Inaugurato nel 1817 ad un progetto dell''architetto Regency Sir John Soane, divenne un punto di riferimento nell''architettura museale attraverso il suo uso innovativo della luce naturale. Originariamente parte del College of God''s Gift, la fondazione caritativa fondata da Edward Alleyn all''inizio del XVII secolo, la galleria divenne una fiducia caritativa indipendente nel 1994.',
  editorial_hook_en='Dulwich Picture Gallery is an art gallery in Dulwich, south London, and the oldest public art gallery in England.', editorial_hook_it='Dulwich Picture Gallery è una galleria d''arte a Dulwich, nel sud di Londra, e la più antica galleria d''arte pubblica in Inghilterra.',
  official_url='https://www.dulwichpicturegallery.org.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-F7BE57EF' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://en.wikipedia.org/wiki/Dulwich_Picture_Gallery','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-F7BE57EF'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Roca London Gallery is an exhibition and event space designed by Zaha Hadid Architects for the bathroom manufacturer Roca. Flowing concrete surfaces, water-like forms and an undulating façade make the architecture the principal exhibit, supplemented by displays on design, materials and water use.', description_it='Roca London Gallery è uno spazio espositivo ed eventi progettato da Zaha Hadid Architects per il produttore del bagno Roca. Le superfici in cemento fluente, forme acquose e una facciata ondulata rendono l''architettura la principale mostra, integrata da display su design, materiali e uso dell''acqua.',
  editorial_hook_en='Roca London Gallery is an exhibition and event space designed by Zaha Hadid Architects for the bathroom manufacturer Roca.', editorial_hook_it='Roca London Gallery è uno spazio espositivo ed eventi progettato da Zaha Hadid Architects per il produttore del bagno Roca.',
  official_url='https://www.rocalondongallery.com/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-903A4988' AND category='MUSEUM';
