SELECT id,'https://www.rocalondongallery.com/','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-903A4988'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Cartoon Museum is a cosy, friendly spot celebrating British cartoon, comic and caricature art. Exhibitions display original strips, political cartoons and illustration; workshops, family activities and talks bring creativity to life. A welcoming shop, rotating displays and knowledgeable staff make it ideal for curious visitors and families. Compact galleries reward a relaxed visit; check opening times for special events and workshops. Guided tours and family trails add extra fun and insight also.', description_it='Cartoon Museum è un luogo accogliente e amichevole che celebra il cartone animato britannico, l''arte comica e caricatura. Mostre mostrano strisce originali, cartoni animati politici e illustrazione; workshop, attività familiari e colloqui portano alla vita la creatività. Un negozio accogliente, display rotanti e personale competente lo rendono ideale per visitatori e famiglie curiosi. Le gallerie compatte premiano una visita rilassata; verificano i tempi di apertura per eventi speciali e workshop. Visite guidate e percorsi familiari aggiungono divertimento e intuizioni extra.',
  editorial_hook_en='Cartoon Museum is a cosy, friendly spot celebrating British cartoon, comic and caricature art.', editorial_hook_it='Cartoon Museum è un luogo accogliente e amichevole che celebra il cartone animato britannico, l''arte comica e caricatura.',
  official_url='https://www.cartoonmuseum.org/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='M6' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://www.cartoonmuseum.org/','official-or-authoritative','2026-10-14' FROM places WHERE id='M6'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Brent Museum, inside The Library at Willesden Green, explores the borough’s social history and the communities that shaped it. Archaeology, domestic objects, photographs and oral histories chart suburban growth, migration, work and entertainment, while temporary displays revisit local stories in greater detail.', description_it='Brent Museum, all’interno della Biblioteca di Willesden Green, esplora la storia sociale del quartiere e le comunità che la hanno plasmata. Archeologia, oggetti domestici, fotografie e storie orali tracciano la crescita suburbana, la migrazione, il lavoro e l''intrattenimento, mentre le esposizioni temporanee rivisitano le storie locali in modo più dettagliato.',
  editorial_hook_en='Brent Museum, inside The Library at Willesden Green, explores the borough’s social history and the communities that shaped it.', editorial_hook_it='Brent Museum, all’interno della Biblioteca di Willesden Green, esplora la storia sociale del quartiere e le comunità che la hanno plasmata.',
  official_url='https://www.brent.gov.uk/libraries-arts-and-heritage/brent-museum-and-archives', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-8EF8132B' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://www.brent.gov.uk/libraries-arts-and-heritage/brent-museum-and-archives','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-8EF8132B'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='This pin marks the British Red Cross’s working UK office rather than a public museum. The charity’s museum and archive collections document humanitarian work, nursing, uniforms, medals and emergency response, but consultation is normally arranged through its archive service rather than by walking into the office.', description_it='Questo perno segna l''ufficio del Regno Unito di lavoro della Croce Rossa britannica piuttosto che un museo pubblico. Le collezioni di musei e archivi della carità documentano il lavoro umanitario, l’allattamento, le uniformi, le medaglie e la risposta d’emergenza, ma la consultazione è di norma organizzata attraverso il suo servizio d’archivio piuttosto che camminare in ufficio.',
  editorial_hook_en='This pin marks the British Red Cross’s working UK office rather than a public museum.', editorial_hook_it='Questo perno segna l''ufficio del Regno Unito di lavoro della Croce Rossa britannica piuttosto che un museo pubblico.',
  official_url='https://www.redcross.org.uk/about-us/our-history/museum-and-archives', access_notes_en='Public access is limited, event-led or by prior arrangement rather than guaranteed daily. Check the official site and confirm a visit before making a special journey.', access_notes_it='L’accesso pubblico è limitato, legato a eventi o su prenotazione e non è garantito ogni giorno. Controlla il sito ufficiale e conferma la visita prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-6070D3F8' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://www.redcross.org.uk/about-us/our-history/museum-and-archives','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-6070D3F8'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Headstone Manor and Museum occupies a rare moated medieval manor complex and tells the history of Harrow. Galleries across restored farm buildings use archaeology, maps, photographs and everyday objects to explain the area’s rural estates, suburban expansion and changing communities.', description_it='Headstone Manor and Museum occupa un raro complesso medievale moated e racconta la storia di Harrow. Le gallerie di edifici agricoli restaurati utilizzano archeologia, mappe, fotografie e oggetti quotidiani per spiegare le proprietà rurali della zona, l''espansione suburbana e le comunità mutevoli.',
  editorial_hook_en='Headstone Manor and Museum occupies a rare moated medieval manor complex and tells the history of Harrow.', editorial_hook_it='Headstone Manor and Museum occupa un raro complesso medievale moated e racconta la storia di Harrow.',
