UPDATE places SET description_en='The RSA Interpretation Centre preserves the history of the Royal Small Arms Factory at Enfield Lock beneath the former factory clock tower. Oral histories, archival material and industrial objects explain weapons manufacture and the lives of employees; access is generally by arrangement or during announced community open days.', description_it='Il RSA Interpretation Centre conserva la storia della Royal Small Arms Factory di Enfield Lock sotto l''ex torre dell''orologio di fabbrica. Storie orali, materiali d''archivio e oggetti industriali spiegano la fabbricazione di armi e la vita dei dipendenti; l''accesso è generalmente di accordo o durante i giorni aperti della comunità annunciati.',
  editorial_hook_en='The RSA Interpretation Centre preserves the history of the Royal Small Arms Factory at Enfield Lock beneath the former factory clock tower.', editorial_hook_it='Il RSA Interpretation Centre conserva la storia della Royal Small Arms Factory di Enfield Lock sotto l''ex torre dell''orologio di fabbrica.',
  official_url='https://rsaf.org.uk/', access_notes_en='Public access is limited, event-led or by prior arrangement rather than guaranteed daily. Check the official site and confirm a visit before making a special journey.', access_notes_it='L’accesso pubblico è limitato, legato a eventi o su prenotazione e non è garantito ogni giorno. Controlla il sito ufficiale e conferma la visita prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-A010C70A' AND category='MUSEUM';
