ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Museum of Neoliberalism is a small, pointed display created by artist Darren Cullen in Lee Green. Satirical objects, graphics and timelines examine privatisation, deregulation, outsourcing and their social consequences, presenting an explicitly critical argument rather than a neutral institutional history.', description_it='Il Museo del Neoliberalismo è un piccolo display a punta creato dall''artista Darren Cullen a Lee Green. Oggetti satirici, grafici e linee temporali esaminano la privatizzazione, la deregolamentazione, l''outsourcing e le loro conseguenze sociali, presentando un argomento esplicitamente critico piuttosto che una storia istituzionale neutrale.',
  editorial_hook_en='The Museum of Neoliberalism is a small, pointed display created by artist Darren Cullen in Lee Green.', editorial_hook_it='Il Museo del Neoliberalismo è un piccolo display a punta creato dall''artista Darren Cullen a Lee Green.',
  official_url='https://www.spellingmistakescostlives.com/museumofneoliberalism', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-7563846F' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://www.spellingmistakescostlives.com/museumofneoliberalism','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-7563846F'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

