ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Museum of Croydon is a museum located within the Croydon Clocktower arts facility in Central Croydon, England. It showcases historical and cultural artefacts relating to the London Borough of Croydon and its people. The museum is owned and run by Croydon Council. It is located on the upper ground floor of Croydon Clocktower, but also incorporates the Riesco Gallery, on the lower ground floor, which displays Roman and Anglo-Saxon collections and a collection of Chinese ceramics.', description_it='Il Museo di Croydon è un museo situato all''interno della struttura di arti orologiere Croydon a Central Croydon, Inghilterra. Presenta reperti storici e culturali relativi al London Borough di Croydon e al suo popolo. Il museo è di proprietà e gestito da Croydon Council. Si trova al piano terra superiore di Croydon Clocktower, ma incorpora anche la Galleria Riesco, al piano terra inferiore, che mostra collezioni romane e anglosassone e una collezione di ceramiche cinesi.',
  editorial_hook_en='The Museum of Croydon is a museum located within the Croydon Clocktower arts facility in Central Croydon, England.', editorial_hook_it='Il Museo di Croydon è un museo situato all''interno della struttura di arti orologiere Croydon a Central Croydon, Inghilterra.',
  official_url='https://www.museumofcroydon.com/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-3465C4C1' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
