ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Institute of Making is a multidisciplinary research club based at University College London. Composed of the Materials Library and the MakeSpace, its work focuses on hands-on research into materials and making from many different perspectives. Members are encouraged to "make, break, design and combine both advanced and traditional tools, techniques and materials".', description_it='The Institute of Making è un club di ricerca multidisciplinare con sede all''Università College di Londra. Composto dalla Biblioteca dei Materiali e dal MakeSpace, il suo lavoro si concentra sulla ricerca pratica sui materiali e facendo da molte prospettive diverse. I membri sono incoraggiati a "fare, rompere, progettare e combinare strumenti, tecniche e materiali avanzati e tradizionali".',
  editorial_hook_en='The Institute of Making is a multidisciplinary research club based at University College London.', editorial_hook_it='The Institute of Making è un club di ricerca multidisciplinare con sede all''Università College di Londra.',
  official_url='', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-689E121E' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://en.wikipedia.org/wiki/Institute_of_Making','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-689E121E'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

