UPDATE places SET description_en='The Royal Academy of Music (RAM) in Westminster, London, England, is one of the oldest music schools in the United Kingdom, founded in 1822 by John Fane and Nicolas-Charles Bochsa. It received its royal charter in 1830 from King George IV with the support of the first Duke of Wellington. The academy provides undergraduate and postgraduate training across instrumental performance, composition, jazz, musical theatre and opera, and recruits musicians from around the world, with a student community representing more than 50 nationalities.', description_it='La Royal Academy of Music (RAM) di Westminster, Londra, Inghilterra, è una delle più antiche scuole di musica del Regno Unito, fondata nel 1822 da John Fane e Nicolas-Charles Bochsa. Ricevette la sua carta reale nel 1830 da re Giorgio IV con il sostegno del primo duca di Wellington. L''accademia fornisce formazione universitaria e post-laurea attraverso performance strumentali, composizione, jazz, teatro musicale e opera, e recluta musicisti da tutto il mondo, con una comunità studentesca che rappresenta più di 50 nazionalità.',
  editorial_hook_en='The Royal Academy of Music (RAM) in Westminster, London, England, is one of the oldest music schools in the United Kingdom, founded in 1822 by John Fane and Nicolas-Charles Bochsa.', editorial_hook_it='La Royal Academy of Music (RAM) di Westminster, Londra, Inghilterra, è una delle più antiche scuole di musica del Regno Unito, fondata nel 1822 da John Fane e Nicolas-Charles Bochsa.',
  official_url='https://ram.ac.uk', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-5B16B057' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
