UPDATE places SET description_en='Bletchley Park is an English country house and estate in Bletchley, Milton Keynes (Buckinghamshire), that became the principal centre of Allied code-breaking during the Second World War. During World War II, the estate housed the Government Code and Cypher School (GC&CS), which regularly penetrated the secret communications of the Axis powers – most importantly the German Enigma and Lorenz ciphers.', description_it='Bletchley Park è una casa di campagna inglese a Bletchley, Milton Keynes (Buckinghamshire), che divenne il centro principale di Allied code-breaking durante la seconda guerra mondiale. Durante la seconda guerra mondiale, la proprietà ospitava il Codice del Governo e la Cypher School (GC&CS), che penetrava regolarmente le comunicazioni segrete dei poteri dell''Asse, soprattutto i cifrari tedeschi Enigma e Lorenz.',
  editorial_hook_en='Bletchley Park is an English country house and estate in Bletchley, Milton Keynes (Buckinghamshire), that became the principal centre of Allied code-breaking during the Second World War.', editorial_hook_it='Bletchley Park è una casa di campagna inglese a Bletchley, Milton Keynes (Buckinghamshire), che divenne il centro principale di Allied code-breaking durante la seconda guerra mondiale.',
  official_url='https://www.bletchleypark.org.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-CABE21B4' AND category='MUSEUM';
