UPDATE places SET description_en='London Museum of Water & Steam is an independent museum founded in 1975 as the Kew Bridge Steam Museum. It was rebranded in early 2014 following a major investment project. Situated on the site of the old Kew Bridge Pumping Station in Brentford, near Kew Bridge on the River Thames in West London, England, the museum is centred on a collection of stationary water pumping steam engines dating from 1820 to 1910.', description_it='London Museum of Water & Steam è un museo indipendente fondato nel 1975 come Kew Bridge Steam Museum. È stato rinominato all''inizio del 2014 a seguito di un importante progetto di investimento. Situato sul sito della vecchia stazione di pompaggio Kew Bridge a Brentford, vicino a Kew Bridge sul fiume Tamigi a Londra ovest, Inghilterra, il museo è incentrato su una collezione di motori a vapore a pompaggio acqua stazionaria dal 1820 al 1910.',
  editorial_hook_en='London Museum of Water & Steam is an independent museum founded in 1975 as the Kew Bridge Steam Museum.', editorial_hook_it='London Museum of Water & Steam è un museo indipendente fondato nel 1975 come Kew Bridge Steam Museum.',
  official_url='https://waterandsteam.org.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-322A2B26' AND category='MUSEUM';
