UPDATE places SET description_en='Croydon Airport Visitor Centre occupies part of the world’s first purpose-built international airport terminal, opened in 1928. Displays and guided visits interpret early airlines, pioneering flights, customs and control-tower operations at the airport that served London before Heathrow took over its role.', description_it='Il Croydon Airport Visitor Centre occupa una parte del primo terminal internazionale aeroportuale, inaugurato nel 1928. Le esposizioni e le visite guidate interpretano le prime compagnie aeree, i voli pionieristici, le operazioni doganali e di controllo in aeroporto che servivano Londra prima che Heathrow assumesse il suo ruolo.',
  editorial_hook_en='Croydon Airport Visitor Centre occupies part of the world’s first purpose-built international airport terminal, opened in 1928.', editorial_hook_it='Il Croydon Airport Visitor Centre occupa una parte del primo terminal internazionale aeroportuale, inaugurato nel 1928.',
  official_url='https://www.historiccroydonairport.org.uk/', access_notes_en='Public access is limited, event-led or by prior arrangement rather than guaranteed daily. Check the official site and confirm a visit before making a special journey.', access_notes_it='L’accesso pubblico è limitato, legato a eventi o su prenotazione e non è garantito ogni giorno. Controlla il sito ufficiale e conferma la visita prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
