UPDATE places SET description_en='Ben Brown Fine Arts is a commercial gallery in Mayfair presenting post-war and contemporary art. Its London programme combines exhibitions by represented artists with historically framed projects involving figures such as Lucio Fontana and Alighiero Boetti, so displays change completely between shows.', description_it='Ben Brown Fine Arts è una galleria commerciale di Mayfair che presenta arte post-bellica e contemporanea. Il suo programma londinese combina mostre di artisti rappresentati con progetti storicamente incorniciati che coinvolgono figure come Lucio Fontana e Alighiero Boetti, così i display cambiano completamente tra spettacoli.',
  editorial_hook_en='Ben Brown Fine Arts is a commercial gallery in Mayfair presenting post-war and contemporary art.', editorial_hook_it='Ben Brown Fine Arts è una galleria commerciale di Mayfair che presenta arte post-bellica e contemporanea.',
  official_url='https://www.benbrownfinearts.com/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-F5CE4043' AND category='MUSEUM';
