SELECT id,'https://www.benbrownfinearts.com/','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-F5CE4043'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The London Transport Museum (LTM) is a transport museum based in Covent Garden, London, England. The museum predominantly hosts exhibits relating to the heritage of London''s transport, as well as conserving and explaining the history of it. The majority of the museum''s exhibits originated in the collections of London Transport, but, since the creation of Transport for London (TfL) in 2000, the remit of the museum has expanded to cover all aspects of transport in the city and in some instances beyond.', description_it='Il London Transport Museum (LTM) è un museo di trasporto con sede a Covent Garden, Londra, Inghilterra. Il museo ospita prevalentemente mostre relative al patrimonio del trasporto londinese, oltre a conservare e spiegare la storia di esso. La maggior parte delle mostre del museo ha avuto origine nelle collezioni di London Transport, ma, dalla creazione di Transport for London (TfL) nel 2000, il remit del museo si è ampliato per coprire tutti gli aspetti del trasporto in città e in alcuni casi oltre.',
  editorial_hook_en='The London Transport Museum (LTM) is a transport museum based in Covent Garden, London, England.', editorial_hook_it='Il London Transport Museum (LTM) è un museo di trasporto con sede a Covent Garden, Londra, Inghilterra.',
  official_url='https://www.ltmuseum.co.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-F4F9FFF4' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://en.wikipedia.org/wiki/London_Transport_Museum','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-F4F9FFF4'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Institute of Contemporary Arts (ICA) is an artistic and cultural centre on The Mall in London, just off Trafalgar Square. Located within Nash House, part of Carlton House Terrace, near the Duke of York Steps and Admiralty Arch, the ICA contains galleries, a theatre, two cinemas, a bookshop and a bar.', description_it='L''Istituto di Arte Contemporanea (ICA) è un centro artistico e culturale sul Mall di Londra, appena fuori Trafalgar Square. Situato all''interno di Nash House, parte di Carlton House Terrace, vicino al duca di York Steps e Admiralty Arch, l''ICA contiene gallerie, un teatro, due cinema, una libreria e un bar.',
  editorial_hook_en='The Institute of Contemporary Arts (ICA) is an artistic and cultural centre on The Mall in London, just off Trafalgar Square.', editorial_hook_it='L''Istituto di Arte Contemporanea (ICA) è un centro artistico e culturale sul Mall di Londra, appena fuori Trafalgar Square.',
  official_url='https://www.ica.art/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-2F39392D' AND category='MUSEUM';
