SELECT id,'https://en.wikipedia.org/wiki/Institute_of_Contemporary_Arts','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-2F39392D'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Hackney Museum uses oral histories, photographs and everyday objects to explore the borough’s communities over roughly a thousand years. Permanent and temporary displays connect migration, work, protest, creativity and family life, with residents’ voices making local experience central to the story.', description_it='Hackney Museum utilizza storie orali, fotografie e oggetti di uso quotidiano per esplorare le comunità del quartiere nel corso di circa mille anni. I display permanenti e temporanei collegano la migrazione, il lavoro, la protesta, la creatività e la vita familiare, con le voci dei residenti che rendono l''esperienza locale centrale alla storia.',
  editorial_hook_en='Hackney Museum uses oral histories, photographs and everyday objects to explore the borough’s communities over roughly a thousand years.', editorial_hook_it='Hackney Museum utilizza storie orali, fotografie e oggetti di uso quotidiano per esplorare le comunità del quartiere nel corso di circa mille anni.',
  official_url='https://hackney.gov.uk/hackney-museum', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-D0969BFB' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://hackney.gov.uk/hackney-museum','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-D0969BFB'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Inns of Court & City Yeomanry is a British Army unit formed through the amalgamation of The Inns of Court Regiment (The Devil''s Own) and The City of London Yeomanry (Rough Riders) in 1961. Its lineage is maintained by 68 (Inns of Court & City Yeomanry) Signal Squadron and the Band of the Royal Yeomanry (Inns of Court & City Yeomanry).', description_it='The Inns of Court & City Yeomanry è un''unità dell''esercito britannico formata attraverso l''amalgamation of The Inns of Court Regiment (The Devil''s Own) e The City of London Yeomanry (Rough Riders) nel 1961. Il suo lignaggio è mantenuto da 68 (Inns of Court & City Yeomanry) Signal Squadron e la Band of the Royal Yeomanry (Inns of Court & City Yeomanry).',
  editorial_hook_en='The Inns of Court & City Yeomanry is a British Army unit formed through the amalgamation of The Inns of Court Regiment (The Devil''s Own) and The City of London Yeomanry (Rough Riders) in 1961.', editorial_hook_it='The Inns of Court & City Yeomanry è un''unità dell''esercito britannico formata attraverso l''amalgamation of The Inns of Court Regiment (The Devil''s Own) e The City of London Yeomanry (Rough Riders) nel 1961.',
  official_url='https://www.army.mod.uk/signals/25849.aspx', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-13F47C94' AND category='MUSEUM';
