UPDATE places SET description_en='Kirkaldy’s Testing Works preserves the Victorian materials-testing workshop opened by engineer David Kirkaldy in 1874. Its huge hydraulic machine, bearing the motto ‘Facts not Opinions’, pulled and crushed full-size samples so engineers could understand the strength of iron, steel and structures.', description_it='Kirkaldy’s Testing Works conserva il laboratorio di test dei materiali vittoriani aperto dall’ingegnere David Kirkaldy nel 1874. La sua enorme macchina idraulica, che porta il motto ''Fatti non Opinioni'', tirato e schiacciato campioni a grandezza naturale in modo che gli ingegneri possano capire la forza di ferro, acciaio e strutture.',
  editorial_hook_en='Kirkaldy’s Testing Works preserves the Victorian materials-testing workshop opened by engineer David Kirkaldy in 1874.', editorial_hook_it='Kirkaldy’s Testing Works conserva il laboratorio di test dei materiali vittoriani aperto dall’ingegnere David Kirkaldy nel 1874.',
  official_url='https://www.testingworks.org.uk/', access_notes_en='Public access is limited, event-led or by prior arrangement rather than guaranteed daily. Check the official site and confirm a visit before making a special journey.', access_notes_it='L’accesso pubblico è limitato, legato a eventi o su prenotazione e non è garantito ogni giorno. Controlla il sito ufficiale e conferma la visita prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-016CF8F3' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://www.testingworks.org.uk/','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-016CF8F3'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Langdon Down Centre preserves Normansfield, the institution founded in 1868 by physician John Langdon Down and his wife Mary for people with learning disabilities. The museum and ornate Victorian theatre document changing care, education and attitudes, including Down’s influential and contested medical legacy.', description_it='Il Langdon Down Centre conserva Normansfield, l''istituzione fondata nel 1868 dal medico John Langdon Down e dalla moglie Mary per le persone disabili. Il museo e il teatro vittoriano ornato documento che cambia la cura, l''istruzione e gli atteggiamenti, tra cui l''eredità medica influente e contestata di Down.',
  editorial_hook_en='The Langdon Down Centre preserves Normansfield, the institution founded in 1868 by physician John Langdon Down and his wife Mary for people with learning disabilities.', editorial_hook_it='Il Langdon Down Centre conserva Normansfield, l''istituzione fondata nel 1868 dal medico John Langdon Down e dalla moglie Mary per le persone disabili.',
  official_url='https://langdondowncentre.org.uk/', access_notes_en='Public access is limited, event-led or by prior arrangement rather than guaranteed daily. Check the official site and confirm a visit before making a special journey.', access_notes_it='L’accesso pubblico è limitato, legato a eventi o su prenotazione e non è garantito ogni giorno. Controlla il sito ufficiale e conferma la visita prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-D8525B31' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://langdondowncentre.org.uk/','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-D8525B31'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The National Maritime Museum (NMM) is a maritime museum in Greenwich, London. It is part of Royal Museums Greenwich, a network of museums in the Maritime Greenwich World Heritage Site. Like other publicly funded national museums in the United Kingdom, it has no general admission charge; there are admission charges for most side-gallery temporary exhibitions, usually supplemented by many loaned works from other museums.', description_it='Il National Maritime Museum (NMM) è un museo marittimo a Greenwich, Londra. Fa parte del Royal Museums Greenwich, una rete di musei del Maritime Greenwich World Heritage Site. Come altri musei nazionali finanziati pubblicamente nel Regno Unito, non ha alcun costo di ammissione generale; ci sono spese di ammissione per la maggior parte delle mostre temporanee di lato-gallery, di solito completato da molte opere prestate da altri musei.',
  editorial_hook_en='The National Maritime Museum (NMM) is a maritime museum in Greenwich, London. It is part of Royal Museums Greenwich, a network of museums in the Maritime Greenwich World Heritage Site.', editorial_hook_it='Il National Maritime Museum (NMM) è un museo marittimo a Greenwich, Londra. Fa parte del Royal Museums Greenwich, una rete di musei del Maritime Greenwich World Heritage Site.',
  official_url='https://www.rmg.co.uk/national-maritime-museum', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-2309DE74' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://en.wikipedia.org/wiki/National_Maritime_Museum','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-2309DE74'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Charles Dickens Museum is an author''s house museum at 48 Doughty Street in Bloomsbury, in the London Borough of Camden. It occupies a typical Georgian terraced house which was Charles Dickens''s home from 25 March 1837 (a year after his marriage) to December 1839.', description_it='Il Charles Dickens Museum è un museo di casa dell''autore a 48 Doughty Street a Bloomsbury, nel London Borough di Camden. Occupa una tipica casa a schiera georgiana che era la casa di Charles Dickens dal 25 marzo 1837 (un anno dopo il suo matrimonio) al dicembre 1839.',
