SELECT id,'https://en.wikipedia.org/wiki/Charles_Dickens_Museum','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-A7D35843'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Jewish Museum London is a museum of British Jewish life, history and identity. It reopened in 2010 after a two-year-long £10 million renovation funded by the Heritage Lottery Fund and other donors. It continues to exist but is currently without permanent premises. The events, programmes and activities at the museum aim to provoke questions, challenge prejudice, and encourage understanding.', description_it='Il Museo ebraico di Londra è un museo della vita ebraica britannica, della storia e dell''identità. Riaprì nel 2010 dopo una ristrutturazione di 10 milioni di sterline di due anni finanziata dal Heritage Lottery Fund e da altri donatori. Continua a esistere, ma attualmente è senza locali permanenti. Gli eventi, i programmi e le attività del museo mirano a suscitare domande, sfidare i pregiudizi e incoraggiare la comprensione.',
  editorial_hook_en='The Jewish Museum London is a museum of British Jewish life, history and identity.', editorial_hook_it='Il Museo ebraico di Londra è un museo della vita ebraica britannica, della storia e dell''identità.',
  official_url='https://www.jewishmuseum.org.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-2F1B1A79' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://en.wikipedia.org/wiki/Jewish_Museum_London','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-2F1B1A79'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

