  editorial_hook_en='Upminster Tithe Barn Museum of Nostalgia fills a large fifteenth-century timber barn with objects from domestic, agricultural and local life.', editorial_hook_it='Upminster Tithe Barn Museum di Nostalgia riempie una grande stalla di legno del XV secolo con oggetti di vita domestica, agricola e locale.',
  official_url='https://www.havering.gov.uk/parks-heritage/upminster-tithe-barn-museum-nostalgia', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-2CABA451' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://www.havering.gov.uk/parks-heritage/upminster-tithe-barn-museum-nostalgia','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-2CABA451'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

