  official_url='https://www.ucl.ac.uk/culture/ucl-art-museum', access_notes_en='Public access is limited, event-led or by prior arrangement rather than guaranteed daily. Check the official site and confirm a visit before making a special journey.', access_notes_it='L’accesso pubblico è limitato, legato a eventi o su prenotazione e non è garantito ogni giorno. Controlla il sito ufficiale e conferma la visita prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-C47B1B24' AND category='MUSEUM';
