UPDATE places SET description_en='The Brunel Museum is a small museum situated at the Brunel Engine House, Rotherhithe, London Borough of Southwark. The Engine House was designed by Sir Marc Isambard Brunel as part of the infrastructure of the Thames Tunnel which opened in 1843 and was the first underwater tunnel to have been built anywhere in the world.', description_it='Il Brunel Museum è un piccolo museo situato presso la Brunel Engine House, Rotherhithe, London Borough di Southwark. La casa motore fu progettata da Sir Marc Isambard Brunel nell''ambito dell''infrastruttura del tunnel Thames che aprì nel 1843 e fu il primo tunnel subacqueo ad essere stato costruito in tutto il mondo.',
  editorial_hook_en='The Brunel Museum is a small museum situated at the Brunel Engine House, Rotherhithe, London Borough of Southwark.', editorial_hook_it='Il Brunel Museum è un piccolo museo situato presso la Brunel Engine House, Rotherhithe, London Borough di Southwark.',
  official_url='https://www.brunel-museum.org.uk', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-B3369E86' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
