UPDATE places SET description_en='The British Museum is a public museum dedicated to human history, art and culture located in the Bloomsbury area of London. Its permanent collection of eight million artefacts is the largest in the world. It documents the story of human culture from its beginnings to the present. Established in 1753, the British Museum was the world''s first public national museum.', description_it='Il British Museum è un museo pubblico dedicato alla storia, all''arte e alla cultura umana situato nella zona di Bloomsbury a Londra. La sua collezione permanente di otto milioni di manufatti è la più grande al mondo. Documenta la storia della cultura umana dai suoi inizi al presente. Fondato nel 1753, il British Museum è stato il primo museo pubblico nazionale al mondo.',
  editorial_hook_en='The British Museum is a public museum dedicated to human history, art and culture located in the Bloomsbury area of London.', editorial_hook_it='Il British Museum è un museo pubblico dedicato alla storia, all''arte e alla cultura umana situato nella zona di Bloomsbury a Londra.',
  official_url='https://www.britishmuseum.org/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-7F9D8D70' AND category='MUSEUM';
