UPDATE places SET description_en='The Bow Street Museum of Crime and Justice is a museum of policing and criminal justice housed on the ground floor of the former police station on Bow Street in Covent Garden, London. It presents Bow Street''s unique place in London''s police history, alongside the story of policing and criminal justice in the area from the eighteenth century until the station''s closure in 1992.', description_it='Il Bow Street Museum of Crime and Justice è un museo di polizia e giustizia criminale ospitato al piano terra dell''ex stazione di polizia di Bow Street a Covent Garden, Londra. Presenta il luogo unico di Bow Street nella storia della polizia di Londra, accanto alla storia della polizia e della giustizia penale nella zona dal XVIII secolo fino alla chiusura della stazione nel 1992.',
  editorial_hook_en='The Bow Street Museum of Crime and Justice is a museum of policing and criminal justice housed on the ground floor of the former police station on Bow Street in Covent Garden, London.', editorial_hook_it='Il Bow Street Museum of Crime and Justice è un museo di polizia e giustizia criminale ospitato al piano terra dell''ex stazione di polizia di Bow Street a Covent Garden, Londra.',
  official_url='', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-96D993DD' AND category='MUSEUM';
