UPDATE places SET description_en='HQS Wellington is a 1934 Grimsby-class sloop moored on the Thames and long associated with the Honourable Company of Master Mariners. Historic interiors, ship models, paintings and maritime objects interpret the vessel’s wartime service and Britain’s merchant-maritime traditions; public access is event-dependent.', description_it='HQS Wellington è uno sloop di classe Grimsby del 1934 ormeggiato sul Tamigi e a lungo associato con l''onorevole Company of Master Mariners. Interni storici, modelli di navi, dipinti e oggetti marittimi interpretano il servizio di guerra della nave e le tradizioni mercantili britanniche; l''accesso pubblico è indipendente dall''evento.',
  editorial_hook_en='HQS Wellington is a 1934 Grimsby-class sloop moored on the Thames and long associated with the Honourable Company of Master Mariners.', editorial_hook_it='HQS Wellington è uno sloop di classe Grimsby del 1934 ormeggiato sul Tamigi e a lungo associato con l''onorevole Company of Master Mariners.',
  official_url='https://www.hqswellington.com/', access_notes_en='Public access is limited, event-led or by prior arrangement rather than guaranteed daily. Check the official site and confirm a visit before making a special journey.', access_notes_it='L’accesso pubblico è limitato, legato a eventi o su prenotazione e non è garantito ogni giorno. Controlla il sito ufficiale e conferma la visita prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-21B77784' AND category='MUSEUM';
