UPDATE places SET description_en='City Wall at Vine Street displays a substantial surviving section of London’s Roman defensive wall inside a modern building. Free interpretation, archaeological objects and reconstructions explain how the wall was built, repaired and absorbed into later structures, revealing nearly two millennia of change on one site.', description_it='Il City Wall di Vine Street presenta una sostanziale sezione sopravvissuta del muro difensivo romano di Londra all''interno di un edificio moderno. Interpretazione gratuita, oggetti archeologici e ricostruzioni spiegano come il muro è stato costruito, riparato e assorbito in strutture successive, rivelando quasi due millenni di cambiamento su un sito.',
  editorial_hook_en='City Wall at Vine Street displays a substantial surviving section of London’s Roman defensive wall inside a modern building.', editorial_hook_it='Il City Wall di Vine Street presenta una sostanziale sezione sopravvissuta del muro difensivo romano di Londra all''interno di un edificio moderno.',
  official_url='https://www.citywallvinestreet.org/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-6FAE5802' AND category='MUSEUM';
