ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Alexander Fleming Laboratory Museum reconstructs the small St Mary’s Hospital laboratory where Fleming discovered penicillin in 1928. Original equipment, photographs and explanatory displays show the accidental observation, later development of the drug and the transformation of modern infection treatment.', description_it='Il Museo del Laboratorio Alexander Fleming ricostruisce il piccolo laboratorio ospedaliero di Santa Maria dove Fleming scoprì la penicillina nel 1928. Attrezzature originali, fotografie e display esplicativi mostrano l''osservazione accidentale, in seguito lo sviluppo del farmaco e la trasformazione del trattamento delle infezioni moderne.',
  editorial_hook_en='The Alexander Fleming Laboratory Museum reconstructs the small St Mary’s Hospital laboratory where Fleming discovered penicillin in 1928.', editorial_hook_it='Il Museo del Laboratorio Alexander Fleming ricostruisce il piccolo laboratorio ospedaliero di Santa Maria dove Fleming scoprì la penicillina nel 1928.',
  official_url='https://www.imperial.nhs.uk/about-us/who-we-are/our-history/alexander-fleming-laboratory-museum', access_notes_en='Public access is limited, event-led or by prior arrangement rather than guaranteed daily. Check the official site and confirm a visit before making a special journey.', access_notes_it='L’accesso pubblico è limitato, legato a eventi o su prenotazione e non è garantito ogni giorno. Controlla il sito ufficiale e conferma la visita prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
