  official_url='https://queerbritain.org.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-0D3C3DC6' AND category='MUSEUM';
