UPDATE places SET description_en='Markfield Road Pumping Station, now known as Markfield Beam Engine and Museum or sometimes just as Markfield Beam Engine is a Grade II listed building containing a 100 horsepower (75 kW) beam engine, originally built in 1886 to pump sewage from Tottenham towards the Beckton Works. The grounds of the building now form a public park known as Markfield Park.', description_it='Markfield Road Pumping Station, ora conosciuto come Markfield Beam Engine and Museum o a volte proprio come Markfield Beam Engine è un edificio classificato Grade II contenente un motore a raggio da 100 cavalli (75 kW), originariamente costruito nel 1886 per pompare la depurazione da Tottenham verso i Beckton Works. I terreni dell''edificio ora formano un parco pubblico noto come Markfield Park.',
  editorial_hook_en='Markfield Road Pumping Station, now known as Markfield Beam Engine and Museum or sometimes just as Markfield Beam Engine is a Grade II listed building containing a 100 horsepower (75 kW) beam engine, originally built in 1886 to pump sewage from Tottenham towar', editorial_hook_it='Markfield Road Pumping Station, ora conosciuto come Markfield Beam Engine and Museum o a volte proprio come Markfield Beam Engine è un edificio classificato Grade II contenente un motore a raggio da 100 cavalli (75 kW), originariamente costruito nel 1886 per pompare la fogna da Tottenham alla guerra',
  official_url='https://www.mbeam.org', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-D2A80796' AND category='MUSEUM';
