UPDATE places SET description_en='Thames River Police Museum is housed at Wapping Police Station, near the base from which the Marine Police began patrolling in 1798. Uniforms, equipment, photographs and case histories trace the world’s oldest continuously operating police force and the changing work of policing the river.', description_it='Thames River Police Museum è ospitato alla stazione di polizia di Wapping, vicino alla base da cui la polizia marina ha iniziato a pattugliare nel 1798. Uniformi, attrezzature, fotografie e case histories tracciano la più antica forza di polizia in continuo funzionamento del mondo e il mutevole lavoro di controllo del fiume.',
  editorial_hook_en='Thames River Police Museum is housed at Wapping Police Station, near the base from which the Marine Police began patrolling in 1798.', editorial_hook_it='Thames River Police Museum è ospitato alla stazione di polizia di Wapping, vicino alla base da cui la polizia marina ha iniziato a pattugliare nel 1798.',
  official_url='https://www.thamespolicemuseum.org.uk/', access_notes_en='Public access is limited, event-led or by prior arrangement rather than guaranteed daily. Check the official site and confirm a visit before making a special journey.', access_notes_it='L’accesso pubblico è limitato, legato a eventi o su prenotazione e non è garantito ogni giorno. Controlla il sito ufficiale e conferma la visita prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-4AB29715' AND category='MUSEUM';
