ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Eltham Palace blends a medieval great hall with a glamorous 1930s Art Deco house, once home to the Courtaulds. Explore lavish interiors, original fittings and atmospheric rooms, then wander formal gardens, a moat and woodland walks. Guided tours, family trails and a café make it ideal for history and design lovers', description_it='Eltham Palace fonde una grande sala medievale con una affascinante casa Art Deco degli anni ''30, una volta sede dei Courtaulds. Esplora gli interni sontuosi, gli arredi originali e le camere atmosferiche, poi vagare giardini formali, un fossato e passeggiate nel bosco. Visite guidate, sentieri per famiglie e un caffè lo rendono ideale per gli amanti della storia e del design',
  editorial_hook_en='Eltham Palace blends a medieval great hall with a glamorous 1930s Art Deco house, once home to the Courtaulds.', editorial_hook_it='Eltham Palace fonde una grande sala medievale con una affascinante casa Art Deco degli anni ''30, una volta sede dei Courtaulds.',
  official_url='https://www.english-heritage.org.uk/visit/places/eltham-palace-and-gardens/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
