ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Little Holland House was the dower house of Holland House in the parish of Kensington, Middlesex, England. It was situated at the end of Nightingale Lane, now the back entrance to Holland Park and was demolished when Melbury Road was made. Number 14 Melbury Road marks its approximate location.', description_it='Little Holland House era la casa dower di Holland House nella parrocchia di Kensington, Middlesex, Inghilterra. Era situato alla fine di Nightingale Lane, ora l''ingresso posteriore a Holland Park ed è stato demolito quando Melbury Road è stato fatto. Numero 14 Melbury Road segna la sua posizione approssimativa.',
