ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Museum of the Home explores how domestic life has evolved over the centuries. Step into Rooms Through Time to see changing interiors, wander the Home Galleries to reflect on everyday life, and stroll the Gardens Through Time, which mirror shifts in society and style. With exhibitions, family days, and festivals, it’s a lively place to discover the past—and rethink the present.', description_it='Il Museo della Casa esplora come la vita domestica si è evoluta nel corso dei secoli. Entra in Camere attraverso il tempo per vedere gli interni mutevoli, vagare per le Home Gallerie per riflettere sulla vita quotidiana, e passeggiare i Giardini attraverso il tempo, che lo specchio si sposta nella società e nello stile. Con mostre, giornate di famiglia e festival, è un luogo vivace per scoprire il passato e ripensare il presente.',
  editorial_hook_en='The Museum of the Home explores how domestic life has evolved over the centuries.', editorial_hook_it='Il Museo della Casa esplora come la vita domestica si è evoluta nel corso dei secoli.',
  official_url='https://museumofthehome.org.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='M18' AND category='MUSEUM';
