UPDATE places SET description_en='The Horniman Museum and Gardens grew from Frederick Horniman’s collection and now brings anthropology, natural history, musical instruments and an aquarium together on a hilltop site. The celebrated overstuffed walrus, hands-on displays and sixteen acres of gardens make its cross-cultural collections unusually varied.', description_it='Il Museo Horniman e i Giardini sono cresciuti dalla collezione di Frederick Horniman e ora riunisce antropologia, storia naturale, strumenti musicali e un acquario insieme su un sito collinare. Il celebre tricheco sopraffatto, le vetrine e sedici acri di giardini rendono le sue collezioni interculturali insolitamente variate.',
  editorial_hook_en='The Horniman Museum and Gardens grew from Frederick Horniman’s collection and now brings anthropology, natural history, musical instruments and an aquarium together on a hilltop site.', editorial_hook_it='Il Museo Horniman e i Giardini sono cresciuti dalla collezione di Frederick Horniman e ora riunisce antropologia, storia naturale, strumenti musicali e un acquario insieme su un sito collinare.',
  official_url='https://www.horniman.ac.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-7B42E937' AND category='MUSEUM';
