UPDATE places SET description_en='The London Archives, previously known as the Greater London Record Office (1965–1997) and London Metropolitan Archives (1997–2024) is the principal local government archive repository for the Greater London area, including the City of London. It is administered and financed by the City of London Corporation, and is the largest county record office in the United Kingdom.', description_it='L''Archivio di Londra, precedentemente noto come Greater London Record Office (1965–1997) e London Metropolitan Archives (1997–2024) è il principale deposito di archivi del governo locale per la Greater London area, tra cui la City of London. È amministrato e finanziato dalla City of London Corporation, ed è il più grande ufficio di contea nel Regno Unito.',
  editorial_hook_en='The London Archives, previously known as the Greater London Record Office (1965–1997) and London Metropolitan Archives (1997–2024) is the principal local government archive repository for the Greater London area, including the City of London.', editorial_hook_it='L''Archivio di Londra, precedentemente noto come Greater London Record Office (1965–1997) e London Metropolitan Archives (1997–2024) è il principale deposito di archivi del governo locale per la Greater London area, tra cui la City of London.',
  official_url='https://www.cityoflondon.gov.uk/things-to-do/archives-and-city-history/london-metropolitan-archives/Pages/default.aspx', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-339CC5BB' AND category='MUSEUM';
