UPDATE places SET description_en='Black Cultural Archives (BCA) is an archive and heritage centre in Brixton, London, devoted to the histories of people of African and Caribbean descent in Britain. Also known as BCA, it was founded in 1981, by educationalist and historian Len Garrison and others. BCA''s mission is to record, preserve and celebrate the history of people of African descent in Britain.', description_it='Black Cultural Archives (BCA) è un centro di archivio e patrimonio a Brixton, Londra, dedicato alle storie di persone di origine africana e caraibica in Gran Bretagna. Conosciuto anche come BCA, è stato fondato nel 1981, dall''educativo e storico Len Garrison e altri. La missione di BCA è quella di registrare, conservare e celebrare la storia delle persone di discendenza africana in Gran Bretagna.',
  editorial_hook_en='Black Cultural Archives (BCA) is an archive and heritage centre in Brixton, London, devoted to the histories of people of African and Caribbean descent in Britain.', editorial_hook_it='Black Cultural Archives (BCA) è un centro di archivio e patrimonio a Brixton, Londra, dedicato alle storie di persone di origine africana e caraibica in Gran Bretagna.',
  official_url='https://www.bcaheritage.org.uk', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-10C3B58E' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
