UPDATE places SET description_en='Redbridge Museum occupies the Central Library in Ilford and follows local history from early settlements to the diverse modern borough. Archaeology, photographs, recreated settings and residents’ stories examine suburban growth, work, childhood and migration, with regular temporary community exhibitions.', description_it='Redbridge Museum occupa la Biblioteca Centrale di Ilford e segue la storia locale dai primi insediamenti ai diversi quartieri moderni. Archeologia, fotografie, ambientazioni ricreate e storie dei residenti esaminano la crescita suburbana, il lavoro, l''infanzia e la migrazione, con regolari mostre temporanee della comunità.',
  editorial_hook_en='Redbridge Museum occupies the Central Library in Ilford and follows local history from early settlements to the diverse modern borough.', editorial_hook_it='Redbridge Museum occupa la Biblioteca Centrale di Ilford e segue la storia locale dai primi insediamenti ai diversi quartieri moderni.',
  official_url='https://www.redbridge.gov.uk/leisure-sport-and-the-arts/redbridge-museum/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-5DDBDFC1' AND category='MUSEUM';
