ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Marx Memorial Library occupies a historic Clerkenwell building and holds major collections on Marxism, labour history, trade unions and the Spanish Civil War. Visitors can see banners, archives and a mural by Jack Hastings, while research access and guided tours reveal the building’s radical publishing history.', description_it='La Biblioteca commemorativa di Marx occupa uno storico edificio di Clerkenwell e detiene importanti collezioni sul marxismo, la storia del lavoro, i sindacati e la guerra civile spagnola. I visitatori possono vedere striscioni, archivi e un murale di Jack Hastings, mentre l''accesso alla ricerca e le visite guidate rivelano la storia della pubblicazione radicale dell''edificio.',
  editorial_hook_en='The Marx Memorial Library occupies a historic Clerkenwell building and holds major collections on Marxism, labour history, trade unions and the Spanish Civil War.', editorial_hook_it='La Biblioteca commemorativa di Marx occupa uno storico edificio di Clerkenwell e detiene importanti collezioni sul marxismo, la storia del lavoro, i sindacati e la guerra civile spagnola.',
  official_url='https://www.marx-memorial-library.org.uk/', access_notes_en='Public access is limited, event-led or by prior arrangement rather than guaranteed daily. Check the official site and confirm a visit before making a special journey.', access_notes_it='L’accesso pubblico è limitato, legato a eventi o su prenotazione e non è garantito ogni giorno. Controlla il sito ufficiale e conferma la visita prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-C18F6CD8' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
