ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Heath Robinson Museum in Pinner celebrates the witty, inventive work of illustrator William Heath Robinson. Set in Memorial Park, the compact museum displays original drawings, books and models of his famously over‑engineered contraptions. Rotating exhibitions, family activities and hands‑on displays delight children and adults alike. Friendly volunteers, a small shop and park cafés make it a charming, accessible stop for a relaxed visit.', description_it='Il Museo Heath Robinson di Pinner celebra l''inventiva e spiritosa opera dell''illustratore William Heath Robinson. Situato nel Memorial Park, il museo compatto presenta disegni, libri e modelli originali delle sue famose contrapzioni sovra-progettate. Esposizioni in rotazione, attività familiari e esposizioni pratiche deliziano bambini e adulti allo stesso modo. I volontari amichevoli, un piccolo negozio e i caffè del parco lo rendono una fermata affascinante e accessibile per una visita rilassata.',
  editorial_hook_en='Heath Robinson Museum in Pinner celebrates the witty, inventive work of illustrator William Heath Robinson.', editorial_hook_it='Il Museo Heath Robinson di Pinner celebra l''inventiva e spiritosa opera dell''illustratore William Heath Robinson.',
  official_url='https://www.heathrobinsonmuseum.org/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='M14' AND category='MUSEUM';
