UPDATE places SET description_en='The Wiener Holocaust Library is one of the world’s oldest institutions dedicated to documenting the Holocaust and Nazi persecution. Free exhibitions draw on survivor testimony, photographs, documents and books collected since the 1930s, while its reading room supports deeper research into genocide and displacement.', description_it='La Wiener Holocaust Library è una delle più antiche istituzioni del mondo dedicate a documentare la persecuzione dell’Olocausto e dei nazisti. Le mostre gratuite attirano testimonianze, fotografie, documenti e libri sopravvissuti raccolti dagli anni ''30, mentre la sua sala di lettura supporta una ricerca più approfondita sul genocidio e lo spostamento.',
  editorial_hook_en='The Wiener Holocaust Library is one of the world’s oldest institutions dedicated to documenting the Holocaust and Nazi persecution.', editorial_hook_it='La Wiener Holocaust Library è una delle più antiche istituzioni del mondo dedicate a documentare la persecuzione dell’Olocausto e dei nazisti.',
  official_url='https://wienerholocaustlibrary.org/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-8AA58D77' AND category='MUSEUM';
