ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Crystal Palace Museum in Sydenham preserves the story of the great glass palace and its local legacy. Housed in a Victorian lecture hall, the compact museum displays photographs, models, artefacts and audio-visual exhibits that trace the building’s rise, relocation and dramatic demise. Friendly volunteers, school programmes and community events bring history to life; free entry and a small shop make it an easy, rewarding stop. Allow time to explore nearby parkland, cafés and Victorian terraces.', description_it='Crystal Palace Museum di Sydenham conserva la storia del grande palazzo di vetro e della sua eredità locale. Ospitato in una sala conferenze vittoriana, il museo compatto mostra fotografie, modelli, artefatti e mostre audiovisive che tracciano l''ascesa dell''edificio, il trasferimento e la drammatica scomparsa. I volontari amichevoli, i programmi scolastici e gli eventi comunitari portano alla vita la storia; l''ingresso gratuito e un piccolo negozio lo rendono una sosta facile e gratificante. Permettete il tempo di esplorare vicino parco, caffè e terrazze vittoriane.',
  editorial_hook_en='Crystal Palace Museum in Sydenham preserves the story of the great glass palace and its local legacy.', editorial_hook_it='Crystal Palace Museum di Sydenham conserva la storia del grande palazzo di vetro e della sua eredità locale.',
  official_url='https://www.crystalpalaceparktrust.org/pages/crystal-palace-museum', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='M12' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://www.crystalpalaceparktrust.org/pages/crystal-palace-museum','official-or-authoritative','2026-10-14' FROM places WHERE id='M12'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Charlton House is a Jacobean mansion in Charlton, within the Royal Borough of Greenwich in south-east London. Built between 1607 and 1612, it is widely regarded as one of the finest and best-preserved examples of Jacobean domestic architecture in England, and the only complete Jacobean mansion surviving in Greater London following the destruction of Holland House during the Second World War.', description_it='Charlton House è un palazzo giacobino a Charlton, all''interno del Royal Borough di Greenwich nel sud-est di Londra. Costruito tra il 1607 e il 1612, è ampiamente considerato come uno dei migliori e meglio conservati esempi di architettura domestica giacobina in Inghilterra, e l''unico palazzo giacobino completo sopravvissuto in Greater London dopo la distruzione di Holland House durante la seconda guerra mondiale.',
  editorial_hook_en='Charlton House is a Jacobean mansion in Charlton, within the Royal Borough of Greenwich in south-east London.', editorial_hook_it='Charlton House è un palazzo giacobino a Charlton, all''interno del Royal Borough di Greenwich nel sud-est di Londra.',
  official_url='', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-42FF4BB8' AND category='MUSEUM';
