UPDATE places SET description_en='Fenton House is a seventeenth-century merchant’s house with panelled rooms, early keyboard instruments, porcelain, needlework and paintings assembled by Lady Binning. Its walled garden and orchard form a rare historic green enclosure close to the summit of Hampstead.', description_it='Fenton House è una casa mercantile seicentesca con camere a pannelli, strumenti a tastiera precoce, porcellana, cucitura e dipinti assemblati da Lady Binning. Il suo giardino murato e frutteto formano un raro recinto verde storico vicino alla vetta di Hampstead.',
  editorial_hook_en='Fenton House is a seventeenth-century merchant’s house with panelled rooms, early keyboard instruments, porcelain, needlework and paintings assembled by Lady Binning.', editorial_hook_it='Fenton House è una casa mercantile seicentesca con camere a pannelli, strumenti a tastiera precoce, porcellana, cucitura e dipinti assemblati da Lady Binning.',
  official_url='https://www.nationaltrust.org.uk/visit/london/fenton-house-and-garden', access_notes_en='Admission, timed-entry and opening arrangements can change. Check the official site for current tickets, concessions, sold-out periods and temporary closures before travelling.', access_notes_it='Biglietti, fasce orarie e aperture possono cambiare. Controlla il sito ufficiale per prezzi, riduzioni, esaurimenti e chiusure temporanee prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-E24C3E52' AND category='MUSEUM';
