ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Two Temple Place is a jewel-like neo-Gothic mansion on the Embankment, built in 1895 by William Waldorf Astor. Its lavish stonework, carved wood, stained glass and ornate interiors host rotating exhibitions and cultural events. Guided tours reveal hidden details and dramatic rooms. Tucked between Temple and the river, it''s a surprising, intimate stop for architecture lovers and curious visitors. Check opening times for exhibitions, talks and events; nearby cafés, riverside are ideal for lingering.', description_it='Two Temple Place è una villa neogotica, costruita nel 1895 da William Waldorf Astor. Le sue lavish stonework, legno intagliato, vetro colorato e interni ornati ospitano mostre rotanti ed eventi culturali. Visite guidate rivelano dettagli nascosti e sale drammatiche. Incastonato tra il Tempio e il fiume, è una sorprendente, intima fermata per gli amanti dell''architettura e visitatori curiosi. Controllare gli orari di apertura per mostre, conferenze ed eventi; caffè nelle vicinanze, lungo il fiume sono ideali per lingering.',
  editorial_hook_en='Two Temple Place is a jewel-like neo-Gothic mansion on the Embankment, built in 1895 by William Waldorf Astor.', editorial_hook_it='Two Temple Place è una villa neogotica, costruita nel 1895 da William Waldorf Astor.',
  official_url='https://twotempleplace.org/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='M3' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
