ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Bentley Priory Museum in Stanmore reveals the country house that became RAF Fighter Command HQ during the Battle of Britain. Explore ornate rooms, a recreated Filter Room, Dowding''s office with immersive film, interactive galleries, Spitfire displays and family trails. Set in parkland with free parking and accessible facilities, it''s a moving, hands-on visit for history lovers and curious families', description_it='Bentley Priory Museum di Stanmore rivela la casa di campagna che divenne quartier generale della RAF Fighter Command durante la battaglia della Gran Bretagna. Esplora le stanze ornate, una Filter Room ricreata, l''ufficio di Dowding con film immersivo, gallerie interattive, display Spitfire e sentieri per famiglie. Situato nel parco con parcheggio gratuito e strutture accessibili, è una visita commovente e pratica per gli amanti della storia e le famiglie curiose',
  editorial_hook_en='Bentley Priory Museum in Stanmore reveals the country house that became RAF Fighter Command HQ during the Battle of Britain.', editorial_hook_it='Bentley Priory Museum di Stanmore rivela la casa di campagna che divenne quartier generale della RAF Fighter Command durante la battaglia della Gran Bretagna.',
  official_url='https://bentleypriorymuseum.org.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='M10' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
