ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Epping Signalling Museum preserves a former London Underground signal cabin beside Epping station. Original levers, diagrams and operating equipment explain how staff controlled trains on the Central line before modern automation; the compact working environment is normally seen only on announced open days.', description_it='Epping Signalling Museum conserva un''ex cabina di segnale della metropolitana di Londra accanto alla stazione Epping. Leve, diagrammi e attrezzature operative originali spiegano come il personale ha controllato i treni sulla linea centrale prima dell''automazione moderna; l''ambiente di lavoro compatto viene normalmente visto solo nei giorni aperti annunciati.',
  editorial_hook_en='Epping Signalling Museum preserves a former London Underground signal cabin beside Epping station.', editorial_hook_it='Epping Signalling Museum conserva un''ex cabina di segnale della metropolitana di Londra accanto alla stazione Epping.',
  official_url='https://www.epping-signalling.org.uk/', access_notes_en='Public access is limited, event-led or by prior arrangement rather than guaranteed daily. Check the official site and confirm a visit before making a special journey.', access_notes_it='L’accesso pubblico è limitato, legato a eventi o su prenotazione e non è garantito ogni giorno. Controlla il sito ufficiale e conferma la visita prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-E0437FA5' AND category='MUSEUM';
