ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='London’s Roman Amphitheatre lies beneath Guildhall Art Gallery, where dark stone outlines at street level mark the arena’s position. Excavated walls, drains and timber remains reveal the venue built for public spectacles in Roman Londinium, interpreted in a free underground display.', description_it='L''Anfiteatro Romano di Londra si trova sotto la Guildhall Art Gallery, dove i contorni di pietra scura a livello stradale segnano la posizione dell''arena. Pareti scosse, scarichi e resti di legname rivelano la sede costruita per gli spettacoli pubblici in Londinium romano, interpretata in un libero display sotterraneo.',
  editorial_hook_en='London’s Roman Amphitheatre lies beneath Guildhall Art Gallery, where dark stone outlines at street level mark the arena’s position.', editorial_hook_it='L''Anfiteatro Romano di Londra si trova sotto la Guildhall Art Gallery, dove i contorni di pietra scura a livello stradale segnano la posizione dell''arena.',
  official_url='https://www.cityoflondon.gov.uk/things-to-do/attractions-museums-entertainment/guildhall-art-gallery/roman-amphitheatre', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-B2AB1D50' AND category='MUSEUM';
