ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Crofton Roman Villa in Crofton, Orpington, in the London Borough of Bromley, is a Roman villa which was inhabited between approximately 140 and 400 AD. It was the centre of a farming estate of about 500 acres (200 ha), with farm buildings nearby, surrounded by fields, meadows and woods. The house was altered several times during its 260 years of occupation, and at its largest it probably had at least 20 rooms.', description_it='Crofton Roman Villa a Crofton, Orpington, nel London Borough di Bromley, è una villa romana abitata tra il 140 e il 400 d.C. Era il centro di una tenuta agricola di circa 500 acri (200 ha), con edifici agricoli nelle vicinanze, circondati da campi, prati e boschi. La casa è stata modificata più volte durante i suoi 260 anni di occupazione, e al suo più grande probabilmente aveva almeno 20 camere.',
  editorial_hook_en='Crofton Roman Villa in Crofton, Orpington, in the London Borough of Bromley, is a Roman villa which was inhabited between approximately 140 and 400 AD.', editorial_hook_it='Crofton Roman Villa a Crofton, Orpington, nel London Borough di Bromley, è una villa romana abitata tra il 140 e il 400 d.C.',
  official_url='https://karu.org.uk/crofton_roman_villa.html', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-6D343958' AND category='MUSEUM';
