UPDATE places SET description_en='Petrie Museum at UCL is a compact, free museum holding over 80,000 Egyptian and Sudanese objects, from everyday tools to rare treasures like the world’s oldest dress. Housed in mahogany-cabinet galleries, it rewards curious visitors with intimate displays, family activities and short, focused visits near the British Museum.', description_it='Il Museo Petrie di UCL è un museo compatto e gratuito che custodisce oltre 80.000 oggetti egiziani e sudanesi, dagli strumenti quotidiani ai tesori rari come il vestito più antico del mondo. Ospitato in gallerie in mogano-cabinetto, premia i visitatori curiosi con esposizioni intime, attività familiari e brevi, visite focalizzate vicino al British Museum.',
  editorial_hook_en='Petrie Museum at UCL is a compact, free museum holding over 80,000 Egyptian and Sudanese objects, from everyday tools to rare treasures like the world’s oldest dress.', editorial_hook_it='Il Museo Petrie di UCL è un museo compatto e gratuito che custodisce oltre 80.000 oggetti egiziani e sudanesi, dagli strumenti quotidiani ai tesori rari come il vestito più antico del mondo.',
  official_url='https://www.ucl.ac.uk/museums-collections/petrie-museum-egyptian-and-sudanese-archaeology', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='M13' AND category='MUSEUM';
