UPDATE places SET description_en='Wimbledon Windmill Museum sits atop Wimbledon Common in a charming 1817 windmill. Free to enter on open days, it showcases milling history, working models and local stories, plus displays on the Scouting movement. Climb narrow stairs for views, watch the sails turn on special weekends, enjoy hands-on exhibits for children and a cosy tearoom nearby. A delightful, family-friendly stop amid wide commons and woodland walks. Open weekends; check sail-turning times and book guided tours in advance!', description_it='Wimbledon Windmill Museum si trova in cima a Wimbledon Common in un affascinante mulino a vento del 1817. Libero di entrare nei giorni aperti, mostra storia di fresatura, modelli di lavoro e storie locali, oltre a esposizioni sul movimento scouting. Salire scale strette per la vista, guardare le vele girano nei weekend speciali, godere di esposizioni hands-on per i bambini e una accogliente sala da tè nelle vicinanze. Una deliziosa e familiare fermata tra ampi comuni e passeggiate nel bosco. Aprire i fine settimana; controllare i tempi di navigazione e prenotare visite guidate in anticipo!',
  editorial_hook_en='Wimbledon Windmill Museum sits atop Wimbledon Common in a charming 1817 windmill.', editorial_hook_it='Wimbledon Windmill Museum si trova in cima a Wimbledon Common in un affascinante mulino a vento del 1817.',
  official_url='https://www.wimbledonwindmill.org.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='M4' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
