ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='Down House, Charles Darwin’s family home in Downe (Bromley), offers a warm, intimate glimpse into the life of the scientist who changed how we see nature. Explore Darwin’s study preserved as he left it, wander the experimental gardens and glasshouses where he tested ideas, and follow family rooms, exhibitions and trails that bring evolution to life. Guided tours, a café and shop make it a relaxed, inspiring day out for curious visitors.', description_it='Down House, casa di famiglia di Charles Darwin a Downe (Bromley), offre uno sguardo caldo e intimo nella vita dello scienziato che ha cambiato come vediamo la natura. Esplora lo studio di Darwin conservato mentre lo lasciava, vagare per i giardini sperimentali e le vetrerie dove ha testato idee, e seguire sale familiari, mostre e percorsi che portano l''evoluzione alla vita. Visite guidate, un caffè e un negozio lo rendono una giornata rilassata e stimolante per i visitatori curiosi.',
  editorial_hook_en='Down House, Charles Darwin’s family home in Downe (Bromley), offers a warm, intimate glimpse into the life of the scientist who changed how we see nature.', editorial_hook_it='Down House, casa di famiglia di Charles Darwin a Downe (Bromley), offre uno sguardo caldo e intimo nella vita dello scienziato che ha cambiato come vediamo la natura.',
  official_url='https://www.english-heritage.org.uk/visit/places/home-of-charles-darwin-down-house/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='M5' AND category='MUSEUM';
