UPDATE places SET description_en='Trent Park House of Secrets interprets the mansion’s covert Second World War role, when captured German generals were held in comfort while British intelligence secretly recorded their conversations. Exhibitions connect those recordings with the estate’s earlier social history and the specialist teams who analysed them.', description_it='Trent Park House of Secrets interpreta il ruolo segreto della seconda guerra mondiale, quando i generali tedeschi catturati sono stati tenuti in comfort mentre l''intelligenza britannica ha registrato segretamente le loro conversazioni. Le esposizioni collegano quelle registrazioni con la storia sociale precedente della tenuta e le squadre specializzate che le hanno analizzate.',
  editorial_hook_en='Trent Park House of Secrets interprets the mansion’s covert Second World War role, when captured German generals were held in comfort while British intelligence secretly recorded their conversations.', editorial_hook_it='Trent Park House of Secrets interpreta il ruolo segreto della seconda guerra mondiale, quando i generali tedeschi catturati sono stati tenuti in comfort mentre l''intelligenza britannica ha registrato segretamente le loro conversazioni.',
  official_url='https://trentparkhouse.org.uk/', access_notes_en='Public access is limited, event-led or by prior arrangement rather than guaranteed daily. Check the official site and confirm a visit before making a special journey.', access_notes_it='L’accesso pubblico è limitato, legato a eventi o su prenotazione e non è garantito ogni giorno. Controlla il sito ufficiale e conferma la visita prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-4E033359' AND category='MUSEUM';
