UPDATE places SET description_en='William Morris Gallery in Walthamstow sits in Water House, a Grade II* Georgian villa set in Lloyd Park. Home to the world’s largest public collection of Morris’s designs, it celebrates his Arts and Crafts legacy with displays, workshops and changing exhibitions. Free to enter, the gallery offers family activities, a shop and a peaceful park setting—ideal for design lovers and curious visitors.', description_it='William Morris Gallery a Walthamstow si trova a Water House, una villa georgiana di grado II* ambientata a Lloyd Park. Casa della più grande collezione pubblica mondiale di disegni di Morris, celebra il suo patrimonio di arti e mestieri con esposizioni, workshop e mostre mutevoli. Libero di entrare, la galleria offre attività familiari, un negozio e un parco tranquillo, ideale per gli amanti del design e i visitatori curiosi.',
  editorial_hook_en='William Morris Gallery in Walthamstow sits in Water House, a Grade II* Georgian villa set in Lloyd Park.', editorial_hook_it='William Morris Gallery a Walthamstow si trova a Water House, una villa georgiana di grado II* ambientata a Lloyd Park.',
  official_url='https://wmgallery.org.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='M2' AND category='MUSEUM';
