  editorial_hook_en='Battle of Britain Bunker at RAF Uxbridge is a compact, atmospheric wartime operations room where No.', editorial_hook_it='Battle of Britain Bunker a RAF Uxbridge è una stanza compatta e atmosferica di guerra dove No.',
  official_url='https://battleofbritainbunker.co.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='M9' AND category='MUSEUM';
