UPDATE places SET description_en='The National Archives in Kew houses over a thousand years of British history in a modern, visitor-friendly building. Browse free exhibitions, consult original documents in the reading rooms with a reader’s ticket, enjoy talks and family activities, and relax in the café and shop. Helpful staff and regular events make it ideal for researchers, history fans and curious visitors; allow a few hours to explore. Seasonal exhibitions, free talks, family trails and on-site research help welcome visitors', description_it='L''Archivio Nazionale di Kew ospita oltre mille anni di storia britannica in un edificio moderno e accogliente. Sfoglia mostre gratuite, consulta i documenti originali nelle sale di lettura con un biglietto del lettore, goditi i colloqui e le attività familiari, e rilassati nella caffetteria e nel negozio. Personale utile e gli eventi regolari lo rendono ideale per ricercatori, appassionati di storia e visitatori curiosi; consentire alcune ore di esplorare. Mostre stagionali, conferenze gratuite, percorsi familiari e ricerche in loco aiutano a accogliere i visitatori',
  editorial_hook_en='The National Archives in Kew houses over a thousand years of British history in a modern, visitor-friendly building.', editorial_hook_it='L''Archivio Nazionale di Kew ospita oltre mille anni di storia britannica in un edificio moderno e accogliente.',
  official_url='https://www.nationalarchives.gov.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='M11' AND category='MUSEUM';
