UPDATE places SET description_en='The Wellcome Collection is a unique museum that explores the connection between medicine, art, and life. Founded by Sir Henry Wellcome, a philanthropist and collector passionate about medical history, it hosts a wide range of exhibitions. You''ll find everything from ancient medical equipment to contemporary artworks that reflect themes of health and well-being. The museum is known for its interactive and provocative exhibits that stimulate curiosity and dialogue about what it means to be human. It has an excellent café, a large and rich shop, and an amazing reading room where you can spend some time relaxing', description_it='La Wellcome Collection è un museo unico che esplora il legame tra medicina, arte e vita. Fondata da Sir Henry Wellcome, un filantropo e collezionista appassionato di storia medica, ospita una vasta gamma di mostre. Troverete tutto, dalle antiche attrezzature mediche alle opere d''arte contemporanee che riflettono temi di salute e benessere. Il museo è noto per le sue esposizioni interattive e provocatorie che stimolano la curiosità e il dialogo su ciò che significa essere umani. Ha un ottimo caffè, un grande e ricco negozio, e una straordinaria sala lettura dove trascorrere un po ''di tempo rilassante',
  editorial_hook_en='The Wellcome Collection is a unique museum that explores the connection between medicine, art, and life.', editorial_hook_it='La Wellcome Collection è un museo unico che esplora il legame tra medicina, arte e vita.',
  official_url='https://www.wellcomecollection.org', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-6749E2E6' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
