ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='V&A East Storehouse at Here East opens the museum’s working collections to public view. Visitors can look into conservation and storage areas, explore objects arranged across disciplines, and request selected works through the Order an Object service, including large pieces rarely displayed in conventional galleries.', description_it='V&A East Storehouse di Here East apre le collezioni di lavoro del museo alla vista pubblica. I visitatori possono guardare in aree di conservazione e stoccaggio, esplorare oggetti disposti su diverse discipline, e richiedere opere selezionate attraverso il servizio Ordine un oggetto, tra cui pezzi di grandi dimensioni raramente visualizzati nelle gallerie convenzionali.',
