UPDATE places SET description_en='The Jewel Tower is a 14th-century surviving element of the Palace of Westminster, in London, England. It was built between 1365 and 1366, under the direction of William of Sleaford and Henry de Yevele, to house the personal treasure of King Edward III. The original tower was a three-storey, crenellated stone building which occupied a secluded part of the palace and was protected by a moat linked to the River Thames.', description_it='La Jewel Tower è un elemento sopravvissuto del Palazzo di Westminster, a Londra, in Inghilterra. Fu costruita tra il 1365 e il 1366, sotto la direzione di Guglielmo di Sleaford e Enrico di Yevele, per ospitare il tesoro personale del re Edoardo III. La torre originale era un edificio in pietra a tre piani che occupava una parte appartata del palazzo ed era protetto da un fossato legato al Tamigi.',
  editorial_hook_en='The Jewel Tower is a 14th-century surviving element of the Palace of Westminster, in London, England.', editorial_hook_it='La Jewel Tower è un elemento sopravvissuto del Palazzo di Westminster, a Londra, in Inghilterra.',
  official_url='https://www.english-heritage.org.uk/visit/places/jewel-tower/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-DE9C9DC5' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
