UPDATE places SET description_en='Museum of the Order of St John at St John’s Gate in Clerkenwell is a compact, atmospheric museum tracing the Order’s story from medieval hospitaller roots to today’s St John Ambulance. Discover armour, illuminated manuscripts, historic medical kit and ceremonial regalia; explore the Norman crypt and chapter rooms on guided tours. Friendly volunteers, hands‑on displays and a small shop make it an engaging, accessible stop for history and medical heritage fans', description_it='Museo dell''Ordine di San Giovanni alla Porta di San Giovanni a Clerkenwell è un museo compatto e atmosferico che traccia la storia dell''Ordine dalle radici ospedaliere medievali all''odierna St John Ambulance. Scopri l''armatura, manoscritti illuminati, kit medico storico e regalia cerimoniale; esplora la cripta normanna e le sale dei capitoli sulle visite guidate. I volontari amichevoli, le esposizioni manuali e un piccolo negozio lo rendono una tappa coinvolgente e accessibile per la storia e i fan del patrimonio medico',
  editorial_hook_en='Museum of the Order of St John at St John’s Gate in Clerkenwell is a compact, atmospheric museum tracing the Order’s story from medieval hospitaller roots to today’s St John Ambulance.', editorial_hook_it='Museo dell''Ordine di San Giovanni alla Porta di San Giovanni a Clerkenwell è un museo compatto e atmosferico che traccia la storia dell''Ordine dalle radici ospedaliere medievali all''odierna St John Ambulance.',
  official_url='https://museumstjohn.org.uk/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='M15' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
