ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The House of Dreams Museum is a terraced house in East Dulwich, England, transformed into the personal art museum of former textile designer and art director Stephen Wright. Wright worked on the museum in secret until the 2010s, when he began to open it to the public several days each year. It is now open to the public ten times a year usually on the last Saturday of the month.', description_it='Il House of Dreams Museum è una casa a schiera a East Dulwich, Inghilterra, trasformata nel museo di arte personale dell''ex designer tessile e art director Stephen Wright. Wright lavorò al museo in segreto fino al 2010, quando cominciò ad aprirlo al pubblico diversi giorni all''anno. Ora è aperto al pubblico dieci volte all''anno di solito l''ultimo sabato del mese.',
  editorial_hook_en='The House of Dreams Museum is a terraced house in East Dulwich, England, transformed into the personal art museum of former textile designer and art director Stephen Wright.', editorial_hook_it='Il House of Dreams Museum è una casa a schiera a East Dulwich, Inghilterra, trasformata nel museo di arte personale dell''ex designer tessile e art director Stephen Wright.',
  official_url='', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-22DC04C5' AND category='MUSEUM';
