UPDATE places SET description_en='Bovril Castle is the local nickname for Kingswood House, an 1811 mansion remodelled in a castellated Jacobethan style for Bovril inventor John Lawson Johnston after 1891. Now run as Kingswood Arts, its great hall, palm court and battlements support performances and community activity rather than a museum display.', description_it='Il castello di Bovril è il soprannome locale di Kingswood House, un palazzo del 1811 rimodellato in uno stile di Jacobethan castellato per l''inventore di Bovril John Lawson Johnston dopo il 1891. Ora eseguire come Kingswood Arts, la sua grande sala, palma e combattimenti sostenere le prestazioni e l''attività comunitaria piuttosto che un display museo.',
  editorial_hook_en='Bovril Castle is the local nickname for Kingswood House, an 1811 mansion remodelled in a castellated Jacobethan style for Bovril inventor John Lawson Johnston after 1891.', editorial_hook_it='Il castello di Bovril è il soprannome locale di Kingswood House, un palazzo del 1811 rimodellato in uno stile di Jacobethan castellato per l''inventore di Bovril John Lawson Johnston dopo il 1891.',
  official_url='https://www.kingswoodarts.com/', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-0D218A21' AND category='MUSEUM';
