UPDATE places SET description_en='The Vagina Museum is the world''s first brick and mortar museum about the female reproductive system. The project is based in the United Kingdom, and moved into its first fixed location in Camden Market, London, in October 2019. Its first exhibition opened on 16 November 2019. It moved to its second premises in Bethnal Green in March 2022 where it remained until February 2023.', description_it='Il Museo della Vagina è il primo museo mondiale di mattoni e mortai sul sistema riproduttivo femminile. Il progetto ha sede nel Regno Unito, e si è trasferito nella sua prima posizione fissa a Camden Market, Londra, nell''ottobre 2019. La sua prima mostra è stata aperta il 16 novembre 2019. Si trasferì nella sua seconda sede a Bethnal Green nel marzo 2022 dove rimase fino al febbraio 2023.',
  editorial_hook_en='The Vagina Museum is the world''s first brick and mortar museum about the female reproductive system.', editorial_hook_it='Il Museo della Vagina è il primo museo mondiale di mattoni e mortai sul sistema riproduttivo femminile.',
  official_url='https://www.vaginamuseum.co.uk', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-4CDDC8D5' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://en.wikipedia.org/wiki/Vagina_Museum','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-4CDDC8D5'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Grant Museum of Zoology and Comparative Anatomy is a natural history museum that is part of University College London in London, England. It was established by Robert Edmond Grant in 1828 as a teaching collection of zoological specimens and material for dissection. It is one of the oldest natural history collections in the UK, and is the last remaining university natural history museum in London.', description_it='Il Grant Museum of Zoology and Comparative Anatomy è un museo di storia naturale che fa parte del University College London a Londra, Inghilterra. Fu fondata da Robert Edmond Grant nel 1828 come raccolta didattica di esemplari zoologici e materiale per dissezione. È una delle più antiche collezioni di storia naturale del Regno Unito, ed è l''ultimo museo di storia naturale dell''università a Londra.',
  editorial_hook_en='The Grant Museum of Zoology and Comparative Anatomy is a natural history museum that is part of University College London in London, England.', editorial_hook_it='Il Grant Museum of Zoology and Comparative Anatomy è un museo di storia naturale che fa parte del University College London a Londra, Inghilterra.',
  official_url='https://www.ucl.ac.uk/culture/grant-museum-zoology', access_notes_en='Opening hours and exhibition schedules can change. Check the official venue site before travelling, especially between temporary shows or for event-day restrictions.', access_notes_it='Orari e calendario delle mostre possono cambiare. Controlla il sito ufficiale prima di partire, soprattutto tra mostre temporanee o in giornate con eventi.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-50246527' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://en.wikipedia.org/wiki/Grant_Museum_of_Zoology_and_Comparative_Anatomy','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-50246527'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Magic Circle’s headquarters contains a museum and library devoted to stage magic and illusion. Posters, apparatus, handcuffs, books and objects associated with celebrated performers document the craft’s history, but the building is a working members’ club and visits are usually through booked events or tours.', description_it='Il quartier generale del Magic Circle contiene un museo e una biblioteca dedicata alla magia scenica e all’illusione. Poster, apparati, manette, libri e oggetti associati a celebri esecutori documentano la storia dell''artigianato, ma l''edificio è un club dei membri del lavoro e le visite sono di solito attraverso eventi o tour prenotati.',
  editorial_hook_en='The Magic Circle’s headquarters contains a museum and library devoted to stage magic and illusion.', editorial_hook_it='Il quartier generale del Magic Circle contiene un museo e una biblioteca dedicata alla magia scenica e all’illusione.',
  official_url='https://themagiccircle.co.uk/', access_notes_en='Public access is limited, event-led or by prior arrangement rather than guaranteed daily. Check the official site and confirm a visit before making a special journey.', access_notes_it='L’accesso pubblico è limitato, legato a eventi o su prenotazione e non è garantito ogni giorno. Controlla il sito ufficiale e conferma la visita prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-FABFCAA6' AND category='MUSEUM';
INSERT INTO place_editorial_sources(place_id,source_url,source_kind,verified_at)
SELECT id,'https://themagiccircle.co.uk/','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-FABFCAA6'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Viktor Wynd Museum of Curiosities assembles fine art, natural-history specimens, occult material and deliberately unsettling oddities in a basement in Hackney. Dense cabinets mix genuine artefacts with jokes and inventions, reviving the subjective spirit of a pre-modern cabinet of curiosities.', description_it='Il Viktor Wynd Museum of Curiosities assembla opere d''arte pregiate, esemplari di storia naturale, materiale occulto e inquietanti probabilità in uno scantinato di Hackney. Armadi di Dense mescolano artefatti genuini con scherzi e invenzioni, rivivendo lo spirito soggettivo di un armadio pre-moderno di curiosità.',
  editorial_hook_en='The Viktor Wynd Museum of Curiosities assembles fine art, natural-history specimens, occult material and deliberately unsettling oddities in a basement in Hackney.', editorial_hook_it='Il Viktor Wynd Museum of Curiosities assembla opere d''arte pregiate, esemplari di storia naturale, materiale occulto e inquietanti probabilità in uno scantinato di Hackney.',
  official_url='https://www.thelasttuesdaysociety.org/museum/', access_notes_en='Admission, timed-entry and opening arrangements can change. Check the official site for current tickets, concessions, sold-out periods and temporary closures before travelling.', access_notes_it='Biglietti, fasce orarie e aperture possono cambiare. Controlla il sito ufficiale per prezzi, riduzioni, esaurimenti e chiusure temporanee prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-6A5CD7C6' AND category='MUSEUM';
