SELECT id,'https://www.thelasttuesdaysociety.org/museum/','official-or-authoritative','2026-10-14' FROM places WHERE id='LA-6A5CD7C6'
ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Anaesthesia Heritage Centre holds the Association of Anaesthetists’ museum, archive and library. Instruments, photographs and personal collections trace the development of anaesthesia, pain relief and patient monitoring, including the professional experiences of practitioners in war and civilian medicine.', description_it='Il Centro del Patrimonio dell''Anestesia detiene l''Associazione di Museo, archivio e biblioteca degli Anaestetisti. Strumenti, fotografie e collezioni personali tracciano lo sviluppo di anestesia, sollievo dal dolore e monitoraggio dei pazienti, comprese le esperienze professionali dei praticanti in guerra e medicina civile.',
  editorial_hook_en='The Anaesthesia Heritage Centre holds the Association of Anaesthetists’ museum, archive and library.', editorial_hook_it='Il Centro del Patrimonio dell''Anestesia detiene l''Associazione di Museo, archivio e biblioteca degli Anaestetisti.',
