ON CONFLICT(place_id,source_url) DO UPDATE SET verified_at=excluded.verified_at;

UPDATE places SET description_en='The Old Operating Theatre Museum occupies an eighteenth-century church attic above the former St Thomas’ Hospital. Its surviving 1822 surgical theatre and herb garret reveal pre-anaesthetic operations, medical teaching and the preparation of remedies in one of Europe’s oldest operating-theatre interiors.', description_it='Il vecchio Museo del Teatro Operativo occupa una soffitta della chiesa settecentesca sopra l''ex ospedale di San Tommaso. Il suo superstite teatro chirurgico 1822 e guarnizione di erbe rivelano operazioni preanestetiche, l''insegnamento medico e la preparazione di rimedi in uno dei più antichi interni operativi-teatre d''Europa.',
  editorial_hook_en='The Old Operating Theatre Museum occupies an eighteenth-century church attic above the former St Thomas’ Hospital.', editorial_hook_it='Il vecchio Museo del Teatro Operativo occupa una soffitta della chiesa settecentesca sopra l''ex ospedale di San Tommaso.',
  official_url='https://oldoperatingtheatre.com/', access_notes_en='Admission, timed-entry and opening arrangements can change. Check the official site for current tickets, concessions, sold-out periods and temporary closures before travelling.', access_notes_it='Biglietti, fasce orarie e aperture possono cambiare. Controlla il sito ufficiale per prezzi, riduzioni, esaurimenti e chiusure temporanee prima di partire.',
  last_verified_at='2026-10-14', updated_at=CURRENT_TIMESTAMP
WHERE id='LA-C6BD9F0A' AND category='MUSEUM';
